// The Greek of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/el/index.ts).
export const whatsNew: Record<string, string> = {
  "What's new": 'Τι νέο υπάρχει',
  'What each version changed': 'Τι άλλαξε σε κάθε έκδοση',
  'What each version of Erevos changed, the newest first.': 'Τι άλλαξε σε κάθε έκδοση του Erevos, η νεότερη πρώτη.',
  'Not out yet': 'Δεν έχει βγει ακόμη',
  'This version': 'Αυτή η έκδοση',
  'For you': 'Για σένα',
  'Under the hood': 'Κάτω από το καπό',
  // Not out yet.
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Συνδεδεμένες συσκευές στο ίδιο Wi-Fi**: το τηλέφωνο και ένας υπολογιστής στο ίδιο Wi-Fi ή hotspot δίνουν ο ένας στον άλλον ό,τι αλλάζει απευθείας εκεί, και χωρίς internet. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Οι λογαριασμοί σου Matrix, XMPP και Nostr σε κάθε συνδεδεμένη συσκευή**: κάθε συνδεδεμένη συσκευή τους παίρνει μόνη της, χωρίς επιλογή, και ακολουθούν τις αλλαγές στο τηλέφωνο: όποιον βγεις από εκεί, ή αλλάξεις με άλλον, φεύγει και από τις συσκευές. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**Ίδιες ρυθμίσεις στις συνδεδεμένες συσκευές**: η γλώσσα, η εμφάνιση και η Τελευταία φορά ενεργός που αλλάζεις στο τηλέφωνο ή σε έναν υπολογιστή αλλάζουν και στις άλλες. Μια φωτογραφία πίσω από τις οθόνες, οι κωδικοί, τα PIN και ό,τι αφορά μία μόνο συσκευή μένουν στην καθεμία. Μια συσκευή μπορεί να κρατά τις δικές της: **Ίδιες ρυθμίσεις σε όλες τις συσκευές** στις Συνδεδεμένες συσκευές. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Τελευταία φορά ενεργός**: όταν μια επαφή δεν είναι συνδεδεμένη, η συνομιλία της λέει πότε είχε τελευταία φορά ανοικτό το Erevos, με ακρίβεια λεπτού. Πηγαίνει κρυπτογραφημένο από άκρη σε άκρη, ποτέ στο relay. Είναι ανοικτό, και αμοιβαίο: κλείσ' το στις Ρυθμίσεις → Απόρρητο και ασφάλεια → Τελευταία φορά ενεργός, και κανείς δεν βλέπει τη δική σου, ούτε εσύ των άλλων. Οι κρυφές συνομιλίες έχουν δική τους ώρα και δικό τους διακόπτη, στις λεπτομέρειες μιας συνομιλίας εκεί. Δες [Συνομιλία μέσω relay](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Μία δημόσια ροή**: το νέο κουμπί **Δημόσια** στην αρχική οθόνη δείχνει σε μία ροή, όπως στο Amethyst, τις δημόσιες αναρτήσεις των ανθρώπων Nostr που ακολουθείς και τα δημόσια δωμάτια Matrix όπου είσαι, με τις φωτογραφίες μέσα στις αναρτήσεις και μια κάρτα για κάθε σύνδεσμο. Απάντησε, αναδημοσίευσε, βάλε «Μου αρέσει», μοιράσου και γράψε νέες αναρτήσεις με φωτογραφίες· στο Matrix, απάντησε, αντέδρασε και μοιράσου. Οι **Φωτογραφίες** ορίζουν αν οι φωτογραφίες έρχονται αμέσως, μόνο μέσω Tor ή με πάτημα. Το κουμπί **Nostr** δείχνει πάλι μόνο τις συνομιλίες Nostr. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Συλλογή**: ένας κρυπτογραφημένος χώρος σε κάθε χώρο και κάθε κρυφό μέρος για φωτογραφίες, αρχεία και φακέλους, με το εικονίδιό της δίπλα στο λουκέτο. Ενεργοποίησέ την στις Ενότητες. Δες τη [Συλλογή](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Μουσική, βίντεο και PDF στη Συλλογή**: η μουσική και τα βίντεο παίζουν από τα κρυπτογραφημένα κομμάτια τους, η μουσική και με την οθόνη σβηστή, με αναπαραγωγή, παύση, επόμενο και προηγούμενο στην οθόνη κλειδώματος, και τα PDF διαβάζονται σελίδα σελίδα μέσα στο Erevos. Το **Άνοιγμα με άλλη εφαρμογή** δεν αφήνει αντίγραφο, και μια φωτογραφία ή ένα βίντεο από τη γκαλερί μπορεί να σβηστεί από εκεί μετά την εισαγωγή. Δες τη [Συλλογή](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**Η Συλλογή στον υπολογιστή**: στην εφαρμογή για υπολογιστή σε Linux, macOS και Windows η Συλλογή κρατά κι εκεί τις φωτογραφίες και τα αρχεία σου κρυπτογραφημένα. Φωτογραφίες, PDF, μουσική και βίντεο ανοίγουν μόνο στη μνήμη, ποτέ ως απλό αντίγραφο στον δίσκο, και κλείνουν όταν κλειδώνει ο χώρος. Η **Αποθήκευση στον υπολογιστή** ρωτά πρώτα. Δες τη [Συλλογή](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Αρχεία έως 4 GB στη Συλλογή**: στο Android ένα αρχείο που διαλέγεις από τα αρχεία του τηλεφώνου κρυπτογραφείται καθώς διαβάζεται, χωρίς απλό αντίγραφο πρώτα, οπότε μπαίνει πιο γρήγορα και δεν θέλει διπλό χώρο. Στην εφαρμογή για υπολογιστή παίζουν μουσική και βίντεο έως 1 GB. Δες τη [Συλλογή](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**Η Συλλογή σε server WebDAV**: κάθε χώρος και κάθε κρυφό μέρος μπορεί να αντιγράφει τη Συλλογή του, κρυπτογραφημένη, σε έναν φάκελο σε server που διαλέγεις, Nextcloud, ownCloud ή όποιον μιλά WebDAV, ώστε τα μεγάλα αρχεία να μην είναι μόνο στο τηλέφωνο. Πηγαίνει μόνο ό,τι είναι καινούργιο, και ένα τηλέφωνο που δεν έχει κάποιο αρχείο το φέρνει από εκεί. Δες τη [Συλλογή](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**Η Συλλογή στις συνδεδεμένες συσκευές σου**: άνοιξε το **Και στις συνδεδεμένες συσκευές μου** στις ρυθμίσεις μιας Συλλογής και αυτή η Συλλογή πηγαίνει στις συνδεδεμένες συσκευές του χώρου ή του κρυφού μέρους, μαζί με τις αλλαγές και τα σβησίματα. Οι μικρογραφίες έρχονται αμέσως, το ίδιο το αρχείο στο ίδιο Wi-Fi ή όταν το ανοίξεις, κομμάτι κομμάτι, συνεχίζοντας από εκεί που σταμάτησε όταν κοπεί το δίκτυο. Δες [Συλλογή](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Οι ομάδες μένουν στη συσκευή που διαλέγεις**: στο τηλέφωνο, στο Συνδεδεμένες συσκευές → Οι ομάδες μένουν σε, μετακίνησε τις ομάδες σε έναν συνδεδεμένο υπολογιστή. Τα κλειδιά τους πηγαίνουν εκεί, ποτέ αντίγραφο, κι έτσι οι ομάδες δουλεύουν εκεί και με το τηλέφωνο κλειστό και μπορείς να φτιάξεις καινούργιες εκεί· τα μέλη δεν βλέπουν τίποτα καινούργιο. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Πρόσθεσε κάποιον νέο σε συνδεδεμένη συσκευή χωρίς το τηλέφωνο**: ένας υπολογιστής προσθέτει μόνος του κάποιον με σύνδεσμο επαφής από αυτή την έκδοση, με το τηλέφωνο κλειστό, και του γράφει αμέσως· εκείνος βλέπει τον λογαριασμό σου ως αίτημα, με τον ίδιο αριθμό ασφαλείας, και το τηλέφωνο τον προσθέτει κι αυτό μόλις ανοίξει. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Κλήσεις και αποστολή αργότερα στις συνδεδεμένες συσκευές σου χωρίς το τηλέφωνο**: με μια επαφή με αυτή την έκδοση, ένας υπολογιστής καλεί και δέχεται κλήσεις μόνος του και στέλνει ο ίδιος ένα μήνυμα για αργότερα, με το τηλέφωνο κλειστό, κι ένα αντίγραφο πηγαίνει και σε κάθε συσκευή της, κρατημένο ώσπου να έρθει η ώρα του. Κάθε συσκευή σου δείχνει τι είναι προγραμματισμένο, κι αν το διαγράψεις σε οποιαδήποτε, ακυρώνεται παντού. Δες [Συνδεδεμένες συσκευές](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Στήριξε το Erevos**: πλέον κάθε τρόπος έχει τον κωδικό QR του, ακόμη και το Liberapay και το PayPal. Το PayPal ανοίγει τώρα στον browser.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**Οι συνομιλίες ανοίγουν στο τέλος τους**: μια μεγάλη συνομιλία, ή μία με εισαγμένα μηνύματα, μπορούσε να ανοίξει σε ένα μήνυμα που είχες διαβάσει πριν από πολύ, συχνά μια φωτογραφία, καθώς φόρτωνε παλαιότερα μηνύματα στον δρόμο προς το τέλος. Τώρα ανοίγει στο πιο πρόσφατο μήνυμα, και όταν έχουν έρθει νέα, το βέλος σε πηγαίνει εκεί που έμεινες.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Το Tor κλειστό, αν δεν το ανοίξεις**: ένας νέος χώρος δεν στέλνει τίποτα μέσω Tor, οπότε τα μηνύματα πάνε πιο γρήγορα, και πριν ανοίξει το Tor σε ρωτά πρώτα, αφού τα κάνει πιο αργά. Ένας χώρος που έχεις ήδη κρατά την επιλογή του, στις Ρυθμίσεις → Relay και δίκτυα → Tor. Τα κείμενα μέσω Nostr πάνε τώρα και χωρίς Tor: τότε τα relays Nostr βλέπουν τη διεύθυνση internet του τηλεφώνου σου, ποτέ ποιος έγραψε σε ποιον. Δες [Μέσω Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Μεταφορά συνομιλίας σε χώρο χωρίς relay**: η **Μεταφορά σε άλλο χώρο** σταματούσε εκεί, γιατί εκείνος ο χώρος δεν είχε δικό του relay. Τώρα προτείνει το relay αυτού του χώρου, που εκείνος ο χώρος κρατά από εκεί και πέρα, και φτιάχνει την ουρά εκείνου του χώρου στο relay όταν έχει relay αλλά όχι ακόμα ουρά. Δες [Δεύτερος κωδικός](#second).",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Σπιτικό relay μόνο μέσω Tor**: γύρισε ένα σπιτικό relay σε **Μόνο μέσω Tor** και δεν βλέπει ποτέ τη διεύθυνση του τηλεφώνου σου, όποια κι αν είναι η ρύθμιση του Tor για τα υπόλοιπα. Αν δεν γράψεις token, δίνει ένα για ένα κουπόνι που το relay σου υπογράφει τυφλά, οπότε κανένα από τα δύο relay δεν μπορεί να καταλάβει ποιανού είναι, και δύο χώροι μπορούν να χρησιμοποιούν τα relay ο ένας του άλλου ως σπιτικά relay χωρίς τίποτα να τα συνδέει. Το token έρχεται μέσα στην ώρα, ισχύει 90 ημέρες και το Erevos το ανανεώνει μόνο του. Θέλει Tor, στο Android. Δες [Σπιτικό relay](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Τα κουμπιά της αρχικής οθόνης μένουν κάτω**: μετά τον κωδικό, η **Υπενθύμιση** και η **Νέα συνομιλία** της αρχικής οθόνης μπορούσαν να μένουν στη μέση της οθόνης, πάνω από τις συνομιλίες, με τη λίστα να τελειώνει πάνω από αυτά, ώσπου να βγεις από το Erevos και να ξαναμπείς. Τώρα η οθόνη ρωτά αμέσως το Android αν είναι ανοιχτό πληκτρολόγιο. Δες [Κλείδωμα με κωδικό](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**Οι αναρτήσεις της καρτέλας Nostr έρχονται**: οι **Αναρτήσεις** μπορούσαν να μένουν για πάντα στο **Έλεγχος…** μέσω Tor. Κάθε αναμονή μέσω Tor έπιανε ένα από τα νήματα που μοιράζεται όλη η εφαρμογή, και όταν πιάνονταν όλα, κάθε αναζήτηση των αναρτήσεων περίμενε πίσω από τις άλλες· ένα relay που απάντησε και μετά δεν ήταν πια προσβάσιμο τις κρατούσε σε αναμονή χωρίς τέλος. Τώρα οι αναμονές του Tor έχουν δικά τους νήματα, ένα relay που δεν απαντά αφήνεται μετά από 20 δευτερόλεπτα, και οι αναρτήσεις έρχονται το πολύ σε περίπου δύο λεπτά, με ό,τι βρέθηκε ως τότε. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**Ξανά Linux, Windows και macOS**: η 6.0.0-rc.1 βγήκε χωρίς αυτά, γιατί ο έλεγχος ότι ανοίγει κάθε έκδοση για υπολογιστή δεν αναγνώριζε τον οδηγό της πρώτης εκκίνησης του Erevos. Τώρα τον αναγνωρίζει.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Οι σύνδεσμοι ανοίγουν στο Sailfish OS**: η **Σύνδεση με LPHL**, μια σελίδα δωρεάς ή ένας σύνδεσμος σε συνομιλία δεν άνοιγαν τίποτα εκεί. Τώρα τους ανοίγει το Sailfish OS: μια ιστοσελίδα στον browser, έναν αριθμό στο τηλέφωνο ή στα μηνύματα, μια διεύθυνση στο email.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, και φωτογραφίες και αρχεία στις συνομιλίες XMPP και Nostr, στο Sailfish OS**: εκεί το Erevos δεν έφτανε στους servers τους μέσω HTTPS, οπότε το Matrix δεν συνδεόταν, φωτογραφίες και αρχεία ούτε έρχονταν ούτε έφευγαν, και οι σύνδεσμοι δεν έδειχναν προεπισκόπηση. Τώρα δουλεύουν όπως σε υπολογιστή.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Μια κλήση τηλεφώνου δείχνει την οθόνη της**: με το Erevos ως εφαρμογή τηλεφώνου, μια κλήση που ερχόταν μπορούσε να χτυπά με μαύρη οθόνη και να μην μπορεί να απαντηθεί, όταν ήταν κλειστές οι ειδοποιήσεις πλήρους οθόνης του Android για το Erevos, οι ειδοποιήσεις του Erevos ή οι ειδοποιήσεις του για εισερχόμενες κλήσεις. Τώρα η οθόνη κλήσης ανοίγει μόνη της, και πάνω από την οθόνη κλειδώματος, και ανάβει την οθόνη. Μια κλήση που κρατά πίσω το «Μην ενοχλείτε» έρχεται ακόμα αθόρυβα, με σβηστή οθόνη. Δες [Τηλέφωνο](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**Η αριθμομηχανή δείχνει ένα μεγάλο αποτέλεσμα από την αρχή του**: στην κατακόρυφη θέση, ένα αποτέλεσμα με πολλά δεκαδικά έκρυβε τα πρώτα του ψηφία, που φαίνονταν μόνο με το τηλέφωνο γυρισμένο οριζόντια. Τώρα ένας μεγάλος αριθμός μικραίνει για να χωρέσει, με τα πρώτα του ψηφία πάντα ορατά.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Διάλεξε τον παραλήπτη ενός νέου SMS από τις επαφές σου**: το **Νέο SMS** έχει κουμπί **Επαφές** που ανοίγει τις επαφές σου με αναζήτηση, και όταν γράφεις όνομα ή αριθμό προτείνονται οι επαφές που ταιριάζουν. Μια επαφή με πολλούς αριθμούς δείχνει μια γραμμή για καθέναν, και στο MMS ομάδας κάθε επαφή που διαλέγεις προστίθεται. Με ανοιχτά μόνο τα SMS φαίνονται μόνο οι επαφές του τηλεφώνου. Δες [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Περισσότερα για έναν αριθμό στο Τηλέφωνο**: στο πληκτρολόγιο, το **⋯** δίπλα σε έναν αριθμό που πληκτρολόγησες προσφέρει **Προσθήκη στις επαφές**, **Προσθήκη σε υπάρχουσα επαφή**, **Αποστολή SMS** και **Αντιγραφή του αριθμού**. Τα **Πρόσφατα** και τα **Αγαπημένα** προσφέρουν **Αντιγραφή του αριθμού** και **Άνοιγμα της επαφής**· τα **Αγαπημένα** και **Αποστολή SMS**, και τα **Πρόσφατα** προσθέτουν έναν άγνωστο αριθμό σε υπάρχουσα επαφή. Με το Erevos κλειδωμένο, το Τηλέφωνο εξακολουθεί μόνο να καλεί. Δες το [Τηλέφωνο](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Μια σύντομη δόνηση στο άγγιγμα**: τα πλήκτρα του πληκτρολογίου κλήσεων, η **Κλήση**, το **Τέλος**, η Αποστολή, το Enter του πληκτρολογίου, οι διακόπτες και τα μενού που ανοίγουν δίνουν μια σύντομη δόνηση. Στις **Ρυθμίσεις** → **Εμφάνιση** → **Δόνηση στο άγγιγμα** τη σβήνεις. Δες την [Εμφάνιση](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Διάλεξε τα μέρη του Erevos που χρησιμοποιείς**: οι δικές του συνομιλίες του Erevos, το Τηλέφωνο, τα SMS, και οι συνομιλίες με εφαρμογές Nostr, Matrix και XMPP είναι πλέον ενότητες, όποιες θέλεις ενεργές, και του ίδιου του Erevos, τουλάχιστον μία. Μια ενότητα που είναι ανενεργή δεν ξεκινά και δεν φαίνεται πουθενά, και τα εικονίδια του Τηλεφώνου και των SMS φεύγουν από τις εφαρμογές του τηλεφώνου: το Erevos γίνεται πιο ελαφρύ, ανοίγει πιο γρήγορα και καταναλώνει λιγότερη μπαταρία. Τίποτα δικό της δεν σβήνεται: όλα είναι πάλι εκεί όταν την ξαναενεργοποιήσεις. Η πρώτη εκκίνηση του Erevos το ρυθμίζει όπως ένας οδηγός εγκατάστασης: τη γλώσσα, τις ενότητες και τι πρέπει να τους επιτρέψει το Android· μια ενότητα που ενεργοποιείς αργότερα ζητά ξανά τις άδειές της. Μετά από αυτή την ενημέρωση όλες οι ενότητες μένουν ενεργές μέχρι να τις αλλάξεις στις **Ρυθμίσεις** → **Γενικά** → **Ενότητες**. Δες [Ενότητες](#modules).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Αριθμός σε κάθε εικονίδιο, σε Huawei και Honor**: οι launchers τους δείχνουν πια αριθμό σε κάθε εικονίδιο του Erevos χωριστά, με ανοιχτό τον **Αριθμό στο εικονίδιο**: στο ίδιο το Erevos τα μηνύματα, στο SMS τα αδιάβαστα SMS, στο Τηλέφωνο τις αναπάντητες κλήσεις, στις Επαφές γενέθλια σήμερα. Οι περισσότεροι άλλοι launchers, όπως αυτοί των Pixel και του GrapheneOS, της Samsung και το Kvaesitso, δίνουν την τελεία ή τον αριθμό μιας ειδοποίησης σε όλα τα εικονίδια μιας εφαρμογής το ίδιο, και εκεί το Erevos δεν μπορεί να το αλλάξει. Δες [Εμφάνιση](#appearance).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Δημόσιες αναρτήσεις στην καρτέλα Nostr**: στην αρχική οθόνη, η καρτέλα Nostr δείχνει πρώτα τις **Αναρτήσεις**, τις δημόσιες αναρτήσεις όσων ακολουθεί το κλειδί Nostr σου και όσα αναδημοσίευσαν, με τις πιο πρόσφατες πρώτες, όπως στο Amethyst ή σε ένα κανάλι του Telegram, με τις **Συνομιλίες** ένα πάτημα πιο δίπλα. Οι παλαιότερες έρχονται καθώς φτάνεις στο τέλος, οι πιο πρόσφατες όταν τραβάς τη λίστα προς τα κάτω· πάτα αυτόν που έγραψε μια ανάρτηση για τις αναρτήσεις του ή για να του στείλεις μήνυμα. Μόνο για ανάγνωση, αναζητούνται μέσω Tor, όπως ορίζει ο χώρος, και δεν αποθηκεύονται, και δεν ανοίγονται εικόνες ούτε σύνδεσμοι. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Κρυφές συνομιλίες στις συνδεδεμένες συσκευές σου**: κάθε θέση κρυφών συνομιλιών συνδέεται πια μόνη της, από μέσα της, με την ίδια θέση σε υπολογιστή ή σε browser, με τις **Συνδεδεμένες συσκευές** κάτω από τη λίστα της. Οι συνομιλίες της, τα μηνύματα, οι ομάδες, οι κλήσεις, η Συνομιλία με τον εαυτό μου και οι δικοί της λογαριασμοί Matrix, XMPP και Nostr πηγαίνουν εκεί, και οι επαφές της γράφουν απευθείας εκεί. Τίποτα από αυτό δεν φαίνεται στον χώρο ούτε στις συνδεδεμένες συσκευές του χώρου. Η σύνδεση λειτουργεί όσο η θέση είναι ανοιχτή, και κλειστή επίσης με ανοιχτή τη **Λήψη όσο είναι κλειστές**. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Μεταφορά συνομιλίας σε άλλο χώρο**: στις **Λεπτομέρειες** μιας συνομιλίας, η **Μεταφορά σε άλλο χώρο** την πηγαίνει, με τα μηνύματα, το όνομα, την εικόνα, την εμφάνιση και τις συνομιλίες που εισήχθησαν σε αυτή, στον χώρο του οποίου τον κωδικό γράφεις, όπως η μεταφορά στις κρυφές: ο αριθμός ασφαλείας μένει ίδιος, και το τηλέφωνό τους μαθαίνει αμέσως να γράφει εκεί. Εκείνος ο χώρος μένει κλειστός, και η επιλογή φαίνεται σε κάθε χώρο. Μια συνομιλία δεν παίρνει ποτέ τη θέση μιας άλλης που έχει ήδη εκείνος ο χώρος, ή οι κρυφές συνομιλίες, με το ίδιο πρόσωπο. Δες [Δεύτερος κωδικός](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**Το Erevos δεν σταματά πια όταν είναι ανοιχτά μόνο τα SMS ή οι Επαφές**: από εκεί, η συνομιλία μιας επαφής, ένα SMS, άλλο εικονίδιο ή μια οθόνη που ζητά ξανά τον κωδικό μπορούσαν να κάνουν το Erevos να πει ότι δεν μπόρεσε να ανοίξει (Maximum call stack size exceeded). Τώρα ο κωδικός ανοίγει όλο το Erevos και μετά εκείνη την οθόνη. Κι όταν το Erevos δεν μπορεί να ανοίξει, το **Δοκίμασε ξανά** το ξεκινά πάλι. Δες [Κλείδωμα με κωδικό](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Κάθε εικονίδιο ανοίγει αυτό που λέει**: αφού το Erevos είχε ανοίξει από το εικονίδιο SMS ή από τις πρόσφατες εφαρμογές, ένα άλλο εικονίδιο, το widget ή μια ειδοποίηση μπορούσαν μερικές φορές να δείξουν στη θέση τους τα SMS. Τώρα το καθένα ανοίγει αυτό που λέει. Όταν είναι ανοιχτά μόνο τα SMS ή οι Επαφές, ένα άλλο εικονίδιο ζητά τον κωδικό όπως όταν το Erevos είναι κλειδωμένο και μετά ανοίγει το δικό του μέρος: το εικονίδιο Επαφές μόνο τις επαφές, το ίδιο το εικονίδιο του Erevos όλο το Erevos. Και το Πίσω στην πρώτη οθόνη του Erevos το στέλνει πια στο παρασκήνιο, όπως η Αρχική, ό,τι κι αν το άνοιξε. Δες [Κλείδωμα με κωδικό](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Μόνο οι Επαφές**: όταν το Erevos είναι κλειδωμένο, το εικονίδιο Επαφές, το κουμπί Επαφές του widget και η ειδοποίηση για γενέθλια ζητούν τον κωδικό και μετά ανοίγουν μόνο τις επαφές. Μια συνομιλία, ένα SMS, οι Ρυθμίσεις και η πορτοκαλί κλειδαριά **Ξεκλείδωμα όλων** ζητούν ξανά τον κωδικό και μετά ανοίγουν ολόκληρο το Erevos. Δες [Κλείδωμα με κωδικό](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Παλιά ιδιωτικά μηνύματα στις συνομιλίες Nostr**: το Erevos διαβάζει και τα ιδιωτικά μηνύματα που στέλνονται με τον παλιότερο τρόπο (NIP-04), που το Damus, το Primal και πολλές εφαρμογές ακόμα στέλνουν και κρατούν. Τα δείχνει, παλιά και νέα, στις ίδιες συνομιλίες. Τα relays βλέπουν ποιος έγραψε ένα τέτοιο μήνυμα σε ποιον· το ίδιο το Erevos στέλνει ακόμα μόνο με τον τρόπο του NIP-17. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Δημόσιες αναρτήσεις στις συνομιλίες Nostr**: σε μια συνομιλία με έναν άνθρωπο, οι **Δημόσιες αναρτήσεις** δείχνουν όσα αναρτά για όλους, με τις πιο πρόσφατες πρώτες, μόνο για ανάγνωση. Αναζητούνται μέσω Tor, όπως ορίζει αυτός ο χώρος, και δεν αποθηκεύονται, και δεν ανοίγονται εικόνες ούτε σύνδεσμοι. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Άδεια χρήσης**: οι Ρυθμίσεις → Γενικά → Άδεια χρήσης λένε με ποια άδεια το Erevos είναι ελεύθερο λογισμικό, AGPL-3.0-or-later, τους τρεις πρόσθετους όρους της, ότι δεν έρχεται με καμία εγγύηση, και ποιος το έφτιαξε. Δες [Άδεια χρήσης](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Επικοινωνία**: οι Ρυθμίσεις → Γενικά → Επικοινωνία προσθέτουν τον δημιουργό του Erevos στις επαφές σου, για να του γράφεις μέσα στο ίδιο το Erevos, κρυπτογραφημένα από άκρη σε άκρη, χωρίς αριθμό τηλεφώνου και χωρίς email. Δες [Τι είναι το Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Νέο σετ αυτοκόλλητων, τα Angry Eyes**: 24 πρόσωπα με μεγάλα κίτρινα μάτια σε μαύρο δίσκο, σχεδιασμένα από τον συντηρητή, το καθένα με τις κινήσεις που του έδωσε.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**Η αριθμομηχανή ανοίγει ξανά**: στην 4.0.0-rc.6 έκλεινε μόλις την πατούσες.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Το Erevos ψάχνει όσους ακολουθείς στο Nostr σε περισσότερα relays**: το **Δείξε τους ανθρώπους που ακολουθείς** ρωτά και relays που μαζεύουν τέτοιες λίστες και περισσότερα από τα relays όπου γράφει το κλειδί σου, και τα περιμένει περισσότερο· όταν δεν βρίσκει κανέναν, λέει γιατί και πώς απάντησε το καθένα. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Κωδικός πανικού**: με το κλείδωμα με κωδικό ενεργό, ο **Ορισμός κωδικού πανικού** στο Κουμπί πανικού ορίζει έναν δικό του κωδικό που, αν γραφτεί στην οθόνη κλειδώματος, σβήνει το Erevos όπως το **Σβήσε τα πάντα τώρα**, ενώ η οθόνη δείχνει **Λάθος κωδικός**. Τίποτα δεν δείχνει αν έχει οριστεί. Δες [Κουμπί πανικού](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Αριθμομηχανή στη θέση του Erevos**: στο Android, στα Εικονίδια εκκίνησης, μια αριθμομηχανή που δουλεύει μπορεί να πάρει τη θέση του εικονιδίου του Erevos· ο κωδικός σου, και μετά **=**, ανοίγει το Erevos, που ζητά τον κωδικό του όπως πάντα. Δες [Εμφάνιση](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Η Συνομιλία με τον εαυτό μου και στις συνδεδεμένες συσκευές σου**: σημειώσεις, φωτογραφίες, αρχεία, φωνητικά και υπενθυμίσεις που γράφεις σε μία συσκευή πηγαίνουν στις άλλες, όπως και μια υπενθύμιση που αλλάζεις ή βλέπεις και μια σημείωση που διαγράφεις. Όσες υπήρχαν από πριν πηγαίνουν μία φορά, και προς τις δύο μεριές. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Εκκίνηση όταν ανάβει το τηλέφωνο**: στο Android, στο Στο παρασκήνιο, το Erevos μπορεί να ξεκινά μόνο του αφού ανάψει το τηλέφωνο, ώστε οι χώροι που λένε ότι ήρθε μήνυμα όσο είναι κλειστοί να λένε ήδη «Νέο μήνυμα», ποτέ ποιος χώρος ή τι. Κλειστό αν δεν το διαλέξεις. Δες [Συνομιλία μέσω relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Η αλλαγή του ρολογιού δεν τελειώνει πια την αναμονή μετά από λάθος κωδικούς**: μετριέται με τον δικό χρόνο του τηλεφώνου από τότε που άναψε, που δεν τον ρυθμίζει κανείς· μετά από επανεκκίνηση ξεκινά πάλι από την αρχή. Δες [Κλείδωμα με κωδικό](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**Όσους ακολουθείς στο Nostr τους βρίσκει εκεί που τους κρατά η άλλη σου εφαρμογή**: με κλειδί που έφερες από άλλη εφαρμογή Nostr, το **Δείξε τους ανθρώπους που ακολουθείς** ψάχνει και στα relays όπου γράφει το κλειδί σου, και λέει όταν δεν απάντησε κανένα relay. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Το όνομά σου στο Nostr κρατά το υπόλοιπο προφίλ σου**: η αποθήκευση στο **Το όνομά σου** αλλάζει μόνο το όνομα στο προφίλ σου· μια φωτογραφία ή λόγια που έβαλε εκεί άλλη εφαρμογή του κλειδιού σου μένουν. Πριν, μπορούσαν να σβηστούν. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**Οι οθόνες κατεβαίνουν όταν δεν υπάρχει ανοιχτό πληκτρολόγιο, σε κάθε περίπτωση**: η λίστα και τα κουμπιά της αρχικής οθόνης, ή μια συνομιλία, μπορούσαν ακόμα να μείνουν ψηλά σαν να ήταν ανοιχτό πληκτρολόγιο, αφού αυτό είχε φύγει. Τώρα το Erevos ρωτά το ίδιο το Android αν φαίνεται πληκτρολόγιο, και όταν δεν φαίνεται κατεβαίνουν μέσα σε ένα δευτερόλεπτο.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Η Νέα συνομιλία ανοίγει πιο γρήγορα τις κρυφές συνομιλίες**: κράτα πατημένη τη **Νέα συνομιλία** για μια στιγμή, όχι για ολόκληρο δευτερόλεπτο, και ανοίγει το πεδίο για το PIN των κρυφών συνομιλιών· στο Android το κινητό δονείται μία φορά όταν ανοίγει. Δες [Κρυφές συνομιλίες](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Οι άνθρωποι που ακολουθείς στο Nostr**: στις Συνομιλίες Nostr, κάτω από τη Νέα συνομιλία, το **Δείξε τους ανθρώπους που ακολουθείς** δείχνει τους ανθρώπους που ακολουθεί το κλειδί Nostr σου, με τα ονόματά τους· πάτα έναν για να του γράψεις. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Ποιος φτιάχνει το Erevos, και η άδειά του**: τα Σχετικά με το Erevos λένε πλέον ποιος το φτιάχνει, και κάθε αρχείο του πηγαίου κώδικα λέει σε ποιον ανήκει και με ποια άδεια· η άδεια AGPL-3.0 έχει τρεις πρόσθετους όρους (να μένει το όνομα του δημιουργού, μια αλλαγμένη εκδοχή να λέει ότι είναι αλλαγμένη και να έχει άλλο όνομα). Δες [Τι είναι το Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Αριθμοί στα κουμπιά της αρχικής οθόνης**: κάθε κουμπί πάνω από τις συνομιλίες (Όλα, SMS, Erevos, Matrix, XMPP, Nostr) δείχνει πόσα μηνύματα δεν έχουν διαβαστεί εκεί, ως έναν μικρό αριθμό μετά το όνομά του· οι συνομιλίες και οι ομάδες σε σίγαση δεν μετρούν. Δες [Πρώτα βήματα](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Φωτογραφία σε όλη την οθόνη στις συνομιλίες Matrix, XMPP και Nostr**: πάτα μια φωτογραφία που φαίνεται σε συνομιλία Matrix, XMPP ή Nostr για να τη δεις σε όλη την οθόνη, με μεγέθυνση, γύρισμα μαζί με το τηλέφωνο και Αποθήκευση, όπως στη συνομιλία με μια επαφή. Δες [Matrix](#matrix), [XMPP](#xmpp) και [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Ποιος πήρε και ποιος διάβασε τα μηνύματά σου στις ομάδες**: σε μια ομάδα που δεν είναι δημόσια, τα μηνύματά σου δείχνουν ✓, μετά ✓✓ όταν έφτασαν στο τηλέφωνο κάθε μέλους, και ✓✓✓ όταν τα διάβασαν όλα. Κράτα πατημένο ένα και διάλεξε **Ποιος το διάβασε** για να δεις ποιος το διάβασε και πότε, στο τηλέφωνο ποιου έφτασε και πότε, και ποιος δεν έχει κάνει ακόμα κανένα από τα δύο. Ένα μέλος με παλιότερο Erevos δεν λέει τίποτα. Ένας συνδεδεμένος υπολογιστής δείχνει τα ίδια σημάδια. Δες [Συνομιλία μέσω relay](#relay) και [Ομαδικές συνομιλίες](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Ποιος διάβασε τα μηνύματά σου στο Matrix**: τα μηνύματά σου σε μια συνομιλία Matrix δείχνουν ✓ μόλις τα πάρει ο server του Matrix και ✓✓✓ μόλις τα διαβάσουν όλα τα άλλα μέλη, όπως το λένε οι εφαρμογές Matrix τους στους servers τους· το **Ποιος το διάβασε**, σε ένα μήνυμα που κρατάς πατημένο, δείχνει ποιος το διάβασε και πότε, και ποιος όχι. Το Matrix δεν έχει σημάδι για μήνυμα που έφτασε σε τηλέφωνο, οπότε δεν υπάρχει ✓✓. Δες [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Αθόρυβα μηνύματα ομάδας για τα σημάδια**: το μήνυμα ομάδας που λέει ότι ένα μήνυμα έφτασε ή διαβάστηκε πηγαίνει μόνο στους αποστολείς που αφορά, και ομαδοποιημένο· μετά από 300 τέτοια μηνύματα μόνο σε μερικά μέλη, το επόμενο πηγαίνει σε όλα, ώστε κανένα μέλος να μη μένει πίσω στα κλειδιά MLS του τηλεφώνου (δέχονται άλμα το πολύ 1000). Οι ομάδες που αφήνονται όταν κλείνει ο χώρος τους δεν στέλνουν πια τίποτα. Δες [Ομαδικές συνομιλίες](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Έντονα, πλάγια, κώδικας και κρυφές λέξεις**: σε συνομιλίες και ομάδες, οι λέξεις ανάμεσα σε * γίνονται έντονες, ανάμεσα σε _ πλάγιες, ανάμεσα σε ~ διαγραμμένες, ανάμεσα σε ` κώδικας και ανάμεσα σε || κρύβονται πίσω από μια γκρι μπάρα μέχρι να τις πατήσεις. Δες [Συνομιλία μέσω relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Κρυμμένη φωτογραφία**: κάτω από το + σε μια συνομιλία ή σε μια ομάδα, μια φωτογραφία που φαίνεται θολή μέχρι να την πατήσεις. Δες [Συνομιλία μέσω relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Μήνυμα ασφαλείας**: κάτω από το + σε μια συνομιλία, λόγια προς μια επαφή που το relay στέλνει μόνο του αν δεν ανοίξεις το Erevos για 6 ώρες έως μία εβδομάδα· κάθε φορά που το ανοίγεις, μετατίθενται πάλι. Δες [Συνομιλία μέσω relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Αναφέρεις ένα μέλος σε ομάδα με @**: γράψε @ και διάλεξε ένα μέλος· ειδοποιείται για το μήνυμα ακόμη κι αν έχει σιγήσει την ομάδα. Δες [Ομαδικές συνομιλίες](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Απάντηση, αλλαγή, αντίδραση και διαγραφή στις συνομιλίες XMPP**: κράτα πατημένο ένα μήνυμα σε μια συνομιλία ή ομάδα XMPP για να το απαντήσεις, να αλλάξεις τα λόγια σου, να το διαγράψεις για όλους ή να αντιδράσεις με ένα emoji, όπως κάνουν τα Conversations, Dino, Gajim, Monal και Kaidan· και το **γράφει…** εμφανίζεται όσο γράφει το άλλο πρόσωπο. Δες το [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Δες ποιος γράφει σε μια συνομιλία Matrix**: το **γράφει…** φαίνεται κάτω από μια συνομιλία Matrix όσο κάποιος γράφει σε αυτήν, όπως το λέει ο server του Matrix. Για σένα φαίνεται μόνο αν ανοίξεις το **Να λέει όταν γράφω** στην οθόνη Matrix ή XMPP: κλειστό στην αρχή, γιατί περνά από τον server χωρίς κρυπτογράφηση. Δες [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Αποκλεισμός στο XMPP**: ο Αποκλεισμός, στο κάτω μέρος μιας συνομιλίας XMPP, κρατά τα μηνύματα, τις κλήσεις και τα αιτήματα αυτού του ατόμου μακριά από κάθε εφαρμογή του λογαριασμού σου XMPP· η Άρση αποκλεισμού το αφήνει να περνά ξανά. Δες [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Φωνητικά μηνύματα στις συνομιλίες XMPP**: κράτα πατημένο το μικρόφωνο κάτω από το πεδίο μηνύματος μιας συνομιλίας XMPP για να ηχογραφήσεις, και άφησέ το για να σταλεί· πηγαίνει κρυπτογραφημένο όπως η συνομιλία, όπως το στέλνει το Conversations. Δες [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Ομάδες Matrix από το Erevos**: η Νέα ομάδα, στην οθόνη του Matrix, φτιάχνει κρυπτογραφημένη ομάδα με όνομα και όσους καλείς· η Συμμετοχή σε ομάδα μπαίνει σε μία με τη διεύθυνσή της· η Πρόσκληση, μέσα σε μια ομάδα, καλεί κάποιον άλλον· γράφοντας @ σε μια ομάδα αναφέρεις ένα μέλος, που ειδοποιείται. Δες [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**Το κουμπί πανικού σε υπολογιστή και στο Sailfish OS**: Ρυθμίσεις → Απόρρητο και ασφάλεια → Κουμπί πανικού σβήνει πλέον το Erevos και εκεί, με τα αυτόματα αντίγραφά του αν το διαλέξεις· σε υπολογιστή μετά ξεκινά ξανά σαν καινούργιο. Δες [Κουμπί πανικού](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Κάθε συνομιλία ανοίγει στο τελευταίο της μήνυμα**: οι συνομιλίες με επαφές, οι ομάδες και τα SMS, και οι συνομιλίες Matrix, XMPP και Nostr ανοίγουν όλες στο τελευταίο μήνυμα με τη γραμμή μηνύματος από κάτω, και έχουν στρογγυλά βελάκια προς την αρχή, προς το σημείο που έμεινες (το πρώτο μήνυμα που ήταν νέο όταν την άνοιξες) και προς το τέλος. Δες [Πρώτα βήματα](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**Το κουμπί πανικού λέει πότε αρνήθηκε**: όταν η εφαρμογή πανικού ζήτησε να σβήσει το Erevos ενώ ο διακόπτης ήταν κλειστός, ή υπογραφόταν με άλλο κλειδί, η οθόνη του κουμπιού πανικού το λέει πλέον, με την ώρα. Μια εφαρμογή που περνά σε νέο κλειδί με τον τρόπο που επιτρέπει το Android μένει έμπιστη· αλλιώς μπορείς να την εμπιστευτείς ξανά όπως είναι τώρα. Δες [Κουμπί πανικού](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Τα κουμπιά της αρχικής οθόνης μένουν σε μία γραμμή**: όταν υπήρχε και κουμπί Nostr, Matrix ή XMPP, τα **Ονόματα** πήγαιναν σε δική τους γραμμή και τα κουμπιά μετακινούνταν. Τώρα μένουν σε μία γραμμή που τη σέρνεις στο πλάι, και το επιλεγμένο φαίνεται πάντα.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**Οι οθόνες κατεβαίνουν όταν φύγει το πληκτρολόγιο**: όταν γύριζες από άλλη εφαρμογή με ανοιχτό πληκτρολόγιο, τα κουμπιά της αρχικής οθόνης (ή το πεδίο μιας συνομιλίας) μπορούσαν να μείνουν ψηλά, εκεί που ήταν το πληκτρολόγιο, ώσπου να ανοίξει ξανά πληκτρολόγιο. Τώρα κατεβαίνουν μέσα σε ένα δευτερόλεπτο.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Δες τι γράφεις σε κωδικό ή PIN**: κάθε πεδίο για κωδικό, PIN ή token έχει ένα μάτι στην άκρη του: πάτα το για να δεις τι γράφεις, και ξανά για να κρυφτεί. Την επόμενη φορά είναι πάλι κρυμμένο. Δες [Κλείδωμα με κωδικό](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Μια συνομιλία που διαβάστηκε όσο άνοιγε μένει διαβασμένη**: μηνύματα που διάβασες ενώ η συνομιλία τους άνοιγε ακόμη, όσο το Erevos τελείωνε μια ματιά στο relay, έδειχναν αδιάβαστα στην αρχική οθόνη μόλις γύριζες πίσω. Τώρα σημειώνονται διαβασμένα μόλις φανούν.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Σύνδεσμος για ιστοσελίδα**: στη Νέα συνομιλία → Ο σύνδεσμος επαφής σου, ένας σύνδεσμος για να τον βάλεις σε μια ιστοσελίδα, όπως τη σελίδα επικοινωνίας σου. Ανοίγει μια σελίδα που προτείνει το Erevos σε όποιον δεν το έχει ακόμα, και μετά σε προσθέτει· ό,τι στέλνει έρχεται ως αίτημα μηνύματος. Δες [Συνομιλία μέσω relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Η λήψη μιας ενημέρωσης που κολλά ξαναρχίζει**: όταν η σύνδεση δεν φέρνει τίποτα για αρκετή ώρα, το Erevos ξαναρχίζει μόνο του τη λήψη, τρεις φορές συνολικά, και μετά το λέει με δικά του λόγια. Δες [Ενημερώσεις](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Τα κομμάτια φωτογραφιών μέσω Nostr μένουν με τις συνομιλίες τους**: όσο μια φωτογραφία που έρχεται μέσω Nostr περιμένει τα υπόλοιπα κομμάτια της, αυτά κρατιούνται πια κρυπτογραφημένα μαζί με τον χώρο ή τις κρυφές συνομιλίες για τις οποίες ήρθαν, όχι χωριστά όπου θα μπορούσε κανείς να τα μετρήσει, ώστε τίποτε έξω από τον κωδικό κρυφών συνομιλιών να μη λέει ότι έρχεται σε αυτές μια φωτογραφία. Κομμάτια που κρατήθηκαν πριν πηγαίνουν στις πρώτες συνομιλίες που είναι δική τους η φωτογραφία, ή φεύγουν μετά από τέσσερις μέρες. Δες [Μέσω Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**Κρυπτογραφημένα SMS όταν τίποτε άλλο δεν λειτουργεί, αν το διαλέξεις**: στο Android, όταν αποτύχουν όλα, το relay, το Nostr, τα κοντινά τηλέφωνα και το LoRa, ένα κείμενο σε επαφή Erevos με συνδεδεμένο αριθμό μπορεί να πάει με SMS, κρυπτογραφημένο από άκρη σε άκρη, κρυφό από την εφαρμογή SMS του άλλου. Ανενεργό μέχρι να το ενεργοποιήσεις, για όλες αυτές τις επαφές στις Ρυθμίσεις → Τηλέφωνο και SMS → SMS, ή για μία στις Λεπτομέρειες μιας συνομιλίας. Κοστίζει SMS (3 για ένα σύντομο κείμενο, έως 10 για ένα μεγαλύτερο), και η εταιρεία τηλεφωνίας βλέπει ποιος έγραψε σε ποιον, και πότε. Και τα δύο τηλέφωνα χρειάζονται το Erevos ως εφαρμογή SMS. Δες [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Απάντηση σε κρυφή κλήση με το κουμπί Απάντηση**: στην οθόνη «Εισερχόμενη κλήση» χωρίς όνομα που φέρνει μια κλήση προς τις κρυφές συνομιλίες σου, η **Απάντηση** ζητά πλέον το PIN, όπως το μικρό σημάδι, και το σωστό PIN απαντά στην κλήση· πριν, δεν μπορούσε να συνδέσει, και μόνο το μικρό σημάδι μπορούσε. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**Τα ανεπιθύμητα SMS έρχονται αθόρυβα**: σε Android, ένα SMS που πιάνουν τα λόγια του ίδιου του φίλτρου ανεπιθύμητων, σύνδεσμος με λόγια που πάνε να ξεγελάσουν από αριθμό που δεν είναι επαφή και στον οποίο δεν απάντησες ποτέ, πηγαίνει ακόμα στα Ανεπιθύμητα αλλά δεν δείχνει πια ειδοποίηση ούτε κάνει ήχο. Τα ανεπιθύμητα από τις δικές σου λέξεις και τους κανόνες σου δείχνουν ακόμα ειδοποίηση, γιατί αυτά μένουν κρυπτογραφημένα στον χώρο· με το Φίλτρο ανεπιθύμητων κλειστό, τη δείχνει κάθε SMS. Δες [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Τι νέο υπάρχει, σε δύο μέρη**: κάθε έκδοση λέει πρώτα τι αλλάζει για σένα, και μετά τι άλλαξε κάτω από το καπό: διορθώσεις, ταχύτητα, μπαταρία και ασφάλεια στο εσωτερικό. Δες [Ενημερώσεις](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Τα SMS μιας επαφής δεν μένουν να μετρούν ως νέα**: όταν ανοίγεις τη συνομιλία της διαβάζονται όλα, και τα παλαιότερα, όχι μόνο όσα φαίνονται.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Ένα μήνυμα δεν μένει πια σε αναμονή όταν το Tor δεν φτάνει στο relay**: με το Tor για τα μηνύματα, πάει αμέσως κατευθείαν, όπως λένε οι ρυθμίσεις του Tor. Δες [Μέσω Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Οι ειδοποιήσεις παρασκηνίου δεν σταματούν πια μετά από αλλαγή δικτύου**: όταν η σύνδεση μιας αναμονής στο relay κοβόταν στη μέση (από Wi-Fi σε δεδομένα, επανεκκίνηση του relay), το Erevos έπαιρνε το relay για παλιό, που δεν ξέρει να περιμένει, για όσο έτρεχε: τα μηνύματα των επαφών έρχονταν έως δέκα λεπτά αργότερα, και οι κρυφές συνομιλίες, οι κλειστοί χώροι και τα κρυφά κουδουνίσματα δεν έλεγαν τίποτα ως την επανεκκίνηση του Erevos. Δες [Συνομιλία μέσω relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Μια κλήση που κλείνει αμέσως δεν χτυπά πια**: όταν το κλείσιμο έφτανε στην ίδια ματιά με την κλήση, το τηλέφωνο χτυπούσε 45 δευτερόλεπτα για κλήση που δεν είχε κανέναν. Το ίδιο για ομαδική κλήση που όποιος την άρχισε την άφησε αμέσως. Δες [Συνομιλία μέσω relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Μια κρυφή κλήση χτυπά μία φορά**: μια θέση με Λήψη όσο είναι κλειστές και ουρά κουδουνίσματος χτυπούσε δύο φορές για μία κλήση, και μια κλήση που πήρες όσο οι κρυφές συνομιλίες ήταν ανοιχτές ξαναχτυπούσε μόλις έκλειναν. Δες [Κρυφές συνομιλίες](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**Ο σύνδεσμος επαφής ενός μέλους δεν λέει πια Νέο μήνυμα**: η απάντηση σε ζήτηση από ομάδα μόνο προσθέτει την επαφή, χωρίς ειδοποίηση. Δες [Ομαδικές συνομιλίες](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**Η ειδοποίηση γενεθλίων και η εισερχόμενη κλήση του τηλεφώνου δεν αντικαθιστούν πια η μία την άλλη**: είχαν τον ίδιο αριθμό ειδοποίησης. Δες [Επαφές](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Ένας κλειστός χώρος λέει και για τα μηνύματα των επαφών του**: αφού κάθε επαφή γράφει σε δική της ουρά, ένας χώρος που λέει ότι ήρθε μήνυμα όσο είναι ανοιχτός άλλος έλεγε μόνο για μηνύματα ομάδων και για πρώτα μηνύματα νέων επαφών. Τώρα ρωτά και για τις ουρές των επαφών του, ως 64. Δες [Συνομιλία μέσω relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**Ο οδηγός χρήσης είναι σε όλες τις γλώσσες της εφαρμογής**: δείχνεται σε αυτήν που διάλεξες, και λέει τα κουμπιά όπως τα δείχνει η εφαρμογή. Δες [Γλώσσα](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Η Τοποθεσία βρίσκει πού είσαι, και σε κλειστό χώρο**: το τηλέφωνο ψάχνει μέσω δορυφόρου και μέσω δικτύου μαζί, ένα φύλλο λέει ότι ψάχνει, και όταν δεν βρεθεί τίποτα λέει γιατί, με το Δοκίμασε ξανά. Δες [Συνομιλία μέσω relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**Το εικονίδιο του web app μετρά τα αδιάβαστα**: σε iPhone, με τις ειδοποιήσεις ανοιχτές για τον χώρο, το εικονίδιο του Erevos στην αρχική οθόνη δείχνει πόσα μηνύματα δεν έχεις διαβάσει, ποτέ μιας κρυφής συνομιλίας, εκτός αν το κλείσεις στις Ρυθμίσεις → Ειδοποιήσεις → Αριθμός στο εικονίδιο. Δες [Σε iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Ειδοποιήσεις για κάθε συνομιλία**: στο Android, βάλε μια συνομιλία ή μια ομάδα σε σίγαση για 8 ώρες, μια εβδομάδα ή πάντα, και δώσε στα μηνύματα και στις κλήσεις της δικό τους ήχο, ή κανέναν. Δες [Συνομιλία μέσω relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Μια συνομιλία κλειδωμένη με δικό της PIN μένει κλειδωμένη**: όταν το Erevos της επαφής ξεκινούσε νέα συνομιλία, όπως κάνει περίπου μία φορά τον μήνα, η συνομιλία έχανε το PIN της, και μια δημόσια ομάδα στην οποία ξαναμπήκες έχανε το δικό της. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**Το εικονίδιο του Erevos κρατά τον αριθμό των αδιάβαστων, στο Android**: όταν φεύγεις από το Erevos με αδιάβαστα μηνύματα, μια ειδοποίηση χωρίς ήχο κρατά πόσα είναι μέχρι να τα διαβάσεις, και ο launcher τη δείχνει στο εικονίδιο, ως αριθμό ή τελεία. Το κλείνεις στις Ρυθμίσεις → Ειδοποιήσεις → Αριθμός στο εικονίδιο. Δες [Συνομιλία μέσω relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**Οι ειδοποιήσεις του web app, πιο αξιόπιστες**: κανένα «Νέο μήνυμα» πάνω από το Erevos όσο είναι ανοιχτό, και ένα push που καθυστέρησε όσο το τηλέφωνο ήταν εκτός σύνδεσης δεν μετρά πια μηνύματα που έχεις ήδη διαβάσει (και τα δύο με το relay σου ενημερωμένο), κάθε ειδοποίηση ακούγεται στο Chrome, στο Firefox και στο Edge, επανέρχονται μόνες τους όταν ο browser αλλάζει τη διεύθυνση push του, και οι «Ειδοποιήσεις όταν είναι κλειστό» λένε πότε τις μπλοκάρει ο browser ή πότε το relay σου δεν έχει ενημερωθεί ακόμα ότι είναι κλειστές. Δες [Σε iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**Οι κλήσεις χτυπούν στο web app, στον υπολογιστή και στο Sailfish OS**: μια κλήση που έρχεται όσο το Erevos είναι ανοιχτό χτυπά πια, ενώ έδειχνε μόνο την οθόνη της, και δονεί όπου μπορεί το κινητό. Στο iPhone χτυπά αφού αγγίξεις το Erevos, και όχι στο αθόρυβο. Δες [Σε iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**Το Erevos στον υπολογιστή συνεχίζει να τρέχει με το παράθυρό του κλειστό**: στη γραμμή συστήματος (σε Mac, στο Dock) συνεχίζει να λαμβάνει, μια κλήση χτυπά και φέρνει πίσω το παράθυρο, και μια ειδοποίηση λέει πόσα μηνύματα δεν έχουν διαβαστεί, ποτέ ποιος ή τι. Το κλείνεις στις Ρυθμίσεις → Ειδοποιήσεις → Στο παρασκήνιο. Δες [Σε υπολογιστή](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**Το Erevos στο Sailfish OS ειδοποιεί για μηνύματα και κλήσεις όσο είναι κλειστό**: όσο δεν φαίνεται ή είναι κλειστό, ένα μικρό βοηθητικό πρόγραμμα περιμένει στο relay για τον ανοιχτό χώρο, μια ειδοποίηση λέει πόσα μηνύματα ήρθαν, ποτέ από ποιον ή τι, και μια κλήση χτυπά με τον ήχο κλήσης του τηλεφώνου. Δες [Σε Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**Τα push του relay προς το web app, πιο ανθεκτικά**: ένα push που η υπηρεσία push δεν μπόρεσε να δεχτεί εκείνη τη στιγμή στέλνεται ξανά, μια κλήση περνά μπροστά από τα μηνύματα που περιμένουν τη σειρά τους, και όποιος τρέχει το relay μπορεί να επιτρέψει άλλη υπηρεσία push. Το relay σου χρειάζεται ενημέρωση γι’ αυτό.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    '**Οι Άδειες ελέγχουν κάθε ειδοποίηση που χρησιμοποιεί το Erevos**: στο Android, η ειδοποίηση μηνυμάτων χωρίς ήχο ή με τον δικό ήχο μιας συνομιλίας, και αυτή των υπενθυμίσεων, όταν είναι κλειστές, φαίνονται πλέον εκεί, με ένα κουμπί για την καθεμία. Δες [Συνομιλία μέσω relay](#relay).',
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**Οι κρυφές συνομιλίες λένε τι χρειάζονται οι διακόπτες τους**: η «Ειδοποίηση όταν έρχεται μήνυμα» και το «Χτύπημα κλήσεων όταν είναι κλειστές» το λένε όταν οι Ρυθμίσεις → Ειδοποιήσεις → Στο παρασκήνιο δεν τους αφήνουν να κάνουν τίποτα. Δες [Κρυφές συνομιλίες](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    '**Πιο ακριβή λόγια για τις ειδοποιήσεις**: οι Ρυθμίσεις και ο οδηγός δίνουν τα ίδια τα λόγια των ειδοποιήσεων και λένε τι χρειάζεται η καθεμία. Δες [Συνομιλία μέσω relay](#relay).',
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    '**Οι κλήσεις χτυπούν όπως πρέπει**: με το «Μην ενοχλείτε» μόνο όταν η ειδοποίησή τους επιτρέπεται να περάσει, και με λάθος ρολόι στο τηλέφωνο μόλις ενημερωθεί το relay, και ως το τέλος στο Android 7 και 8· μια δεύτερη κλήση βρίσκει κατειλημμένο, και ένα χτύπημα σταματά μόνο για τη δική του κλήση. Δες [Συνομιλία μέσω relay](#relay).',
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Κρυφές κλήσεις**: μια κλήση που απορρίπτεις δεν αφήνει πια το Erevos πάνω από την οθόνη κλειδώματος, μια που έρχεται όσο φαίνεται η οθόνη κωδικού εμφανίζεται πάνω της, και καμία δεν χτυπά δύο φορές. Δες [Κρυφές συνομιλίες](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Οι ειδοποιήσεις έρχονται ξανά αμέσως μετά από αλλαγή δικτύου**, και η λήψη ξεκινά ξανά μόλις φανεί το Erevos, όταν το Android την είχε αρνηθεί. Δες [Συνομιλία μέσω relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    '**Οι ειδοποιήσεις των κρυφών συνομιλιών λένε κάθε μήνυμα μία φορά**: ό,τι ήρθε από την τελευταία φορά που κοίταξε μια θέση λέγεται όταν κλείνει, μια κλήση που χτύπησε δεν λέγεται ξανά ως μήνυμα, και μια θέση που το relay έχασε την ουρά της κρατά τον διακόπτη της ανοιχτό. Δες [Κρυφές συνομιλίες](#hidden).',
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**Οι κρυφές συνομιλίες κλείνουν όσο το Erevos δεν φαίνεται**, μετά από 30 δευτερόλεπτα, ώστε μια κλήση σε αυτές στο μεταξύ να χτυπά με το PIN τους για να απαντήσεις. Δες [Κρυφές συνομιλίες](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Ένα φωνητικό μήνυμα μετρά μία φορά**, στο τελευταίο του κομμάτι, και όταν ξαναστέλνεται ολόκληρο.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**Ο αριθμός στο εικονίδιο μετρά μόνο ό,τι είναι ακόμα εκεί**: ένα μήνυμα που διαγράφηκε για όλους, ή που διαβάστηκε σε συνδεδεμένο υπολογιστή, δεν μετρά πια. Δες [Συνομιλία μέσω relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**Τα μηνύματα που στέλνονται για αργότερα** ειδοποιούν μόνο όσο ο χώρος τους είναι ανοιχτός, χωρίς ήχο αν στάλθηκαν έτσι.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: ένα για τη συνομιλία που είναι στην οθόνη μόνο ηχεί εκεί, σημειώνονται ως διαβασμένα μόνο όσο φαίνεται η οθόνη τους, και το Android ονομάζει τις ειδοποιήσεις τους SMS. Δες [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    '**Υπενθυμίσεις**: μια υπενθύμιση που είδες στη Συνομιλία με τον εαυτό μου φεύγει από την ειδοποίηση, όσες έχει μια κρυφή θέση φεύγουν με νέο PIN, και τα γενέθλια έρχονται στις 9:00. Δες [Πρώτα βήματα](#start).',
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**Το Nostr διαβάζει μόλις το Tor είναι έτοιμο.** Δες [Μέσω Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    '**Οι ειδοποιήσεις του Erevos δείχνουν το σήμα του** στη γραμμή κατάστασης.',
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Η άδεια για ειδοποιήσεις ζητείται και με τη λήψη κλειστή**, όταν η «Ειδοποίηση για μηνύματα» είναι ανοιχτή.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**Οι φωτογραφίες ανοίγουν σε όλη την οθόνη**: πάτα μία για να τη δεις ως τις άκρες, μεγέθυνε με δύο δάχτυλα ή με διπλό πάτημα, και πάτα ξανά για να κρύψεις ή να δεις ό,τι είναι γύρω της· οι μεγάλες φωτογραφίες ανοίγουν όπως οι μικρές. Το Erevos γυρίζει επίσης μαζί με το τηλέφωνο όσο είναι ανοιχτή η Αυτόματη περιστροφή του, και μια φωτογραφία που βλέπεις μόνη της ακόμα κι όταν είναι κλειστή. Δες [Συνομιλία μέσω relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Λογαριασμοί Matrix στο Erevos**: σύνδεσε έναν χώρο στο Matrix και συνομίλησε με ανθρώπους που χρησιμοποιούν το Element ή άλλη εφαρμογή Matrix, με κρυπτογράφηση από άκρη σε άκρη, στις Ρυθμίσεις → Relay και δίκτυα → Matrix. Αυτές οι συνομιλίες δεν είναι ανώνυμες, και το λένε: ο server του Matrix βλέπει ποιος μιλά με ποιον. Κείμενο, φωτογραφίες και αρχεία. Δες [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**Οι συνομιλίες όλων των δικτύων στην αρχική οθόνη**: μόλις συνδεθείς στο Matrix, οι συνομιλίες του μπαίνουν στη λίστα μαζί με τις συνομιλίες Erevos και τα SMS, οι πιο πρόσφατες πρώτες, η καθεμία με το σημάδι Matrix, και το κουμπί Matrix δείχνει μόνο αυτές, όπως τα SMS και το Erevos. Δες [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Δοκιμαστικές εκδόσεις πριν από μια έκδοση**: το Erevos διαβάζει μια έκδοση όπως η 4.0.0-rc.1, δοκιμαστική έκδοση που έρχεται πριν από την 4.0.0, όταν ψάχνει για ενημερώσεις, όταν λέει ότι βγήκε νέα έκδοση και όταν δείχνει τι νέο υπάρχει. Δες [Ενημερώσεις](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Έλεγχος συσκευών Matrix με emoji**: σε συνομιλία με ένα άτομο στο Matrix, ο Έλεγχος με emoji δείχνει και στους δύο επτά εικόνες· αν ταιριάζουν, κανείς δεν είναι στη μέση, και το Element βλέπει κι αυτό τον έλεγχο. Ο Έλεγχος αυτής της συσκευής με άλλη δική σου κάνει το δικό σου Element να εμπιστεύεται το Erevos. Δες [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Αυτόματα αντίγραφα και στον δικό σου server**: στο Android, κάθε αυτόματο αντίγραφο μπορεί να πηγαίνει και σε έναν φάκελο σε server που διαλέγεις, όπως το Nextcloud σου, μέσω WebDAV. Κλειστό μέχρι να προσθέσεις έναν. Ο server παίρνει τυχαία bytes με τυχαίο όνομα και δεν μπορεί να τα ανοίξει· βλέπει όμως τον λογαριασμό σου, τη διεύθυνσή σου και πότε. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Κλειδί Ασφαλείας και αντίγραφο κλειδιών στο Matrix**: γράψε το Κλειδί Ασφαλείας που έφτιαξε το Element, στις Ρυθμίσεις → Relay και δίκτυα → Matrix, και ανοίγουν τα παλιότερα μηνύματα, τα νέα κλειδιά φυλάγονται, και οι άλλες συσκευές σου εμπιστεύονται το Erevos. Ένας λογαριασμός χωρίς κλειδί μπορεί να φτιάξει ένα εκεί. Δες [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix μέσω Tor**: σε Android, ο λογαριασμός Matrix ενός χώρου ακολουθεί την επιλογή του στις Ρυθμίσεις → Relay και δίκτυα → Tor, οπότε ο server του Matrix δεν βλέπει πια πού βρίσκεσαι· η οθόνη του Matrix λέει πότε πάει μέσω Tor. Δες [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Λογαριασμοί XMPP στο Erevos**: σύνδεσε έναν χώρο στο XMPP, στις Ρυθμίσεις → Relay και δίκτυα → XMPP, και συνομίλησε με ανθρώπους που χρησιμοποιούν το Conversations, το Monal, το Gajim, το Dino ή άλλη εφαρμογή XMPP, κρυπτογραφημένα με OMEMO. Αυτές οι συνομιλίες δεν είναι ανώνυμες και το λένε: ο server XMPP βλέπει ποιος μιλά με ποιον. Κείμενο με σημάδια παράδοσης και ανάγνωσης, φωτογραφίες και αρχεία, στη λίστα της αρχικής οθόνης κάτω από δικό τους κουμπί XMPP, και μέσω Tor σε Android όπως επέλεξες. Δες [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Κλήσεις φωνής και βίντεο με ανθρώπους στο XMPP**: τα δύο πλακίδια στην κορυφή μιας συνομιλίας XMPP καλούν τον άλλον, και οι δικές του κλήσεις χτυπούν στην ίδια οθόνη με του ίδιου του Erevos, με εφαρμογές που καλούν όπως το Conversations. Η κλήση περνά από το relay κλήσεών σου ή του server XMPP, ώστε να μη μαθαίνει τη διεύθυνσή σου· το κλειδί που την αποδεικνύει περνά από τους servers XMPP, που θα μπορούσαν να μπουν στη μέση. Δες [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Κλήσεις φωνής και βίντεο με ανθρώπους στο Matrix**: στο Android, τα δύο πλακίδια στην κορυφή μιας συνομιλίας Matrix καλούν με το Element Call, την εφαρμογή κλήσεων του Element και του Element X, που ανοίγει μέσα στο Erevos σε δικό της παράθυρο, και οι δικές τους κλήσεις χτυπούν εδώ όπως του ίδιου του Erevos. Ήχος και εικόνα είναι κρυπτογραφημένα από άκρο σε άκρο και περνούν από τον server πολυμέσων που ορίζει ο server Matrix σου, ποτέ από Tor. Δες [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Κλήσεις φωνής και βίντεο με ανθρώπους στο Matrix, στην εφαρμογή web και σε υπολογιστή**: τα δύο πλακίδια στην κορυφή μιας συνομιλίας Matrix καλούν με το Element Call και εκεί, όπως στο Android, πάνω από την εφαρμογή· το βέλος επιστροφής του μικραίνει το παράθυρο σε μια γωνία, ώστε να συνεχίζεις να χρησιμοποιείς το Erevos στη διάρκεια της κλήσης. Το Element Call τρέχει χωριστά από το Erevos και δεν μπορεί να διαβάσει τίποτα από αυτό. Δες [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Συνομιλίες με ανθρώπους σε άλλες εφαρμογές Nostr**: δώσε σε έναν χώρο δικό του κλειδί Nostr, στις Ρυθμίσεις → Relay και δίκτυα → Συνομιλίες Nostr, και συνομίλησε με ανθρώπους που χρησιμοποιούν το Damus, το Amethyst, το Primal, το 0xchat ή άλλη εφαρμογή Nostr, ένας με έναν ή σε ομάδες, κρυπτογραφημένα όπως ορίζει το NIP-17: τα relays βλέπουν σε ποιον πάει ένα μήνυμα, όχι ποιος το έγραψε. Αυτές οι συνομιλίες δεν είναι ανώνυμες και το λένε: το κλειδί σου είναι το ίδιο για όλους όσους γράφεις. Κείμενο, φωτογραφίες, αρχεία και αντιδράσεις, στη λίστα της αρχικής οθόνης κάτω από δικό τους κουμπί Nostr, και μέσω Tor σε Android όπως επέλεξες. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Ειδοποιήσεις για μηνύματα Matrix, XMPP και Nostr**: ένα μήνυμα σε συνομιλία Matrix, XMPP ή Nostr δείχνει ειδοποίηση και μετράει στον αριθμό στο εικονίδιο του Erevos, όπως στις συνομιλίες του ίδιου του Erevos. Στο Android, οι Ειδοποιήσεις στο κάτω μέρος μιας τέτοιας συνομιλίας τη βάζουν σε σίγαση ή της δίνουν δικό της ήχο, και μια κλήση XMPP ή Matrix χτυπά με τον ήχο κλήσης της συνομιλίας της. Δες [Matrix](#matrix), [XMPP](#xmpp) και [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Ένας κλειστός χώρος λέει για τα μηνύματα του Matrix**: στο Android, η «Ειδοποίηση για μηνύματα» στο «Όσο αυτός ο χώρος είναι κλειστός», στην οθόνη του Matrix, κάνει έναν κλειστό χώρο να λέει «Νέο μήνυμα» όταν έρχεται κάτι στο Matrix όσο είναι ανοιχτός άλλος χώρος, ποτέ τι, από ποιον ή σε ποια συνομιλία. Κλειστό ώσπου να το διαλέξεις. Ο server του Matrix ειδοποιεί τότε το relay του χώρου για κάθε μήνυμα, χωρίς καμία λέξη του: μαθαίνει τη διεύθυνση του relay, και το relay πότε έρχονται μηνύματα. Δες [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Φτιαγμένο με το ανοιχτό λογισμικό άλλων**: Στα Σχετικά με το Erevos και στον οδηγό αναφέρονται πλέον τα έργα ανοιχτού λογισμικού πάνω στα οποία είναι χτισμένο το Erevos, με τους δημιουργούς τους και τις άδειές τους. Δες [Τι είναι το Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Ομάδες στο XMPP**: στις Ρυθμίσεις → Relay και δίκτυα → XMPP, φτιάξε μια ιδιωτική ομάδα με τις επαφές σου, κρυπτογραφημένη με OMEMO για κάθε μέλος όπως οι ιδιωτικές ομάδες του Conversations, ή μπες σε μια ομάδα με τη διεύθυνσή της, και απάντησε σε προσκλήσεις σε ομάδες. Μια ομάδα που δεν είναι ιδιωτική, ένα κανάλι, δεν είναι κρυπτογραφημένη και το λέει. Οι ομάδες σου ακολουθούν τις άλλες εφαρμογές XMPP του λογαριασμού σου, και ένα κανάλι ειδοποιεί μόνο για μηνύματα που αναφέρουν το όνομά σου. Δες [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Περισσότερα στις συνομιλίες Matrix**: κράτα πατημένο ένα μήνυμα για να του αντιδράσεις, να το απαντήσεις, να το αντιγράψεις και, αν είναι δικό σου, να το επεξεργαστείς ή να το διαγράψεις για όλους. Η «Φόρτωση παλιότερων μηνυμάτων» φέρνει τα παλιότερα, και το μικρόφωνο κάτω από το πεδίο του μηνύματος στέλνει φωνητικά μηνύματα που τα παίζει και το Element. Οι αντιδράσεις δεν είναι κρυπτογραφημένες, όπως τις στέλνει το Element. Δες [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Βίντεο που προστίθεται σε κλήση XMPP**: σε κλήση φωνής με κάποιον στο XMPP, ο καθένας σας μπορεί να ανοίξει βίντεο με την «Προσθήκη βίντεο»· ο άλλος ρωτιέται πρώτος και μπορεί να πει «Όχι τώρα». Δουλεύει με εφαρμογές που προσθέτουν βίντεο σε κλήση όπως το Conversations. Δες [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Φωνητικά μηνύματα και απαντήσεις στις συνομιλίες Nostr**: κράτα πατημένο το μικρόφωνο κάτω από το πεδίο του μηνύματος για να στείλεις φωνητικό μήνυμα, που παίζει με την «Αναπαραγωγή»· κράτα πατημένο ένα μήνυμα για να το απαντήσεις, και η απάντηση δείχνει σε ποιο μήνυμα απαντά, εδώ και στις άλλες εφαρμογές Nostr. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 στις συνομιλίες XMPP**: ένα μήνυμα σε κάποιον που η εφαρμογή του μιλά OMEMO 2, όπως το Kaidan, πηγαίνει πλέον με OMEMO 2 σε εκείνη την εφαρμογή και με OMEMO 0.3 στις υπόλοιπες εφαρμογές του, όπως πριν. Η οθόνη XMPP δείχνει το κλειδί αυτής της συσκευής και με τους δύο τρόπους, για σύγκριση με όσα δείχνει η κάθε εφαρμογή. Δες [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**Οι κρυφές συνομιλίες μπορούν να έχουν δικούς τους λογαριασμούς Matrix, XMPP και Nostr**: κάτω από τη λίστα μιας θέσης κρυφών συνομιλιών, τα Matrix, XMPP και Nostr ανοίγουν έναν λογαριασμό μόνο εκείνης της θέσης, χωριστά από του χώρου και κρυπτογραφημένο με το κλειδί των κρυφών συνομιλιών. Οι συνομιλίες του φαίνονται μόνο ανάμεσα στις κρυφές συνομιλίες. Συνδέεται όσο αυτές είναι ανοιχτές, και όσο είναι κλειστές επίσης, αν η «Λήψη όσο είναι κλειστές» είναι ενεργή, όπως οι ίδιες οι κρυφές συνομιλίες: τότε ένα μήνυμα λέει μόνο «Νέο μήνυμα», και μια κλήση χτυπά χωρίς όνομα και απαντιέται με το PIN. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP και Nostr στα αντίγραφα ασφαλείας**: ένα αντίγραφο κρατά πλέον τους λογαριασμούς Matrix, XMPP και Nostr κάθε χώρου και των κρυφών συνομιλιών του. Μετά από επαναφορά, ένα κλειδί Nostr επανέρχεται με τις συνομιλίες του όπως ήταν· ένας λογαριασμός XMPP συνεχίζει ως νέα συσκευή του λογαριασμού, με τις επαφές και τις συνομιλίες του· ένας λογαριασμός Matrix αποδεσμεύεται από αυτό το τηλέφωνο, και ο χώρος συνδέεται ξανά ως νέα συσκευή· το Κλειδί Ασφαλείας του ανοίγει τα μηνύματα από πριν. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**Τα φωνητικά στο Matrix δείχνουν την κυματομορφή τους, και οι απαντήσεις στο Nostr μπορούν να είναι φωτογραφίες**: ένα φωνητικό που στέλνεις σε συνομιλία Matrix έχει μαζί την κυματομορφή του, που τη ζωγραφίζει το Element, και ένα που έρχεται με κυματομορφή τη δείχνει κάτω από την Αναπαραγωγή· σε συνομιλία Nostr, μια φωτογραφία, ένα αρχείο ή ένα φωνητικό που στέλνεις όσο ένα μήνυμα φαίνεται πάνω από το πεδίο το απαντά. Δες [Matrix](#matrix) και [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Ομαδικές κλήσεις σε ομάδες XMPP**: σε μια ιδιωτική ομάδα XMPP, ξεκίνα μια κλήση φωνής ή βίντεο, απάντησε σε μια που χτυπά ή μπες σε μια που γίνεται, μαζί με ανθρώπους που χρησιμοποιούν το Dino. Δες [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Μια κλήση σε αργό τηλέφωνο χτυπά ολόκληρη**: όποιος καλεί περιμένει πλέον μέχρι ένα λεπτό και ένα τέταρτο να πει το άλλο τηλέφωνο ότι χτυπά, και μετά 45 δευτερόλεπτα από τότε, ώστε μια κλήση που έφτασε εκεί αργά να μη χτυπά για να σταματήσει αμέσως· και το τηλέφωνο που καλείται διαβάζει μια κλήση πριν από ό,τι έχει να στείλει, και περιμένει ξανά κλήσεις αμέσως μόλις αλλάξει δίκτυο. Δες [Συνομιλία μέσω relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Η εφαρμογή web και ο υπολογιστής φτάνουν σε servers Matrix, XMPP και Nostr μέσω HTTPS**: η πολιτική της σελίδας τους επέτρεπε μόνο συνδέσεις WebSocket, οπότε η σύνδεση στο Matrix, η εύρεση του server XMPP και η κοινή χρήση αρχείων, και τα αρχεία και οι αναζητήσεις ονομάτων στο Nostr δεν δούλευαν εκεί. Τώρα δουλεύουν. Δες [Matrix](#matrix), [XMPP](#xmpp) και [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Ένα μήνυμα που στέλνεις όσο ανοίγει μια συνομιλία την περιμένει**, με την ένδειξη Αποστολή…, και φεύγει μόλις ανοίξει, χωρίς να λέει ότι το Erevos δεν μπορεί να κρυπτογραφήσει.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**Ό,τι διαβάζεις όσο ανοίγει μια συνομιλία μένει διαβασμένο**: η αρχική οθόνη δεν το μετρά πια ως νέο.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Καμία ερώτηση από τη Samsung για την «Κοινή χρήση» της**: σε τηλέφωνο Samsung, το Wi-Fi Aware και το Wi-Fi με κοντινά τηλέφωνα μένουν κλειστά μέχρι να τα ανοίξεις. Δες [Συνομιλία με κοντινό τηλέφωνο](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**Το πεδίο του SMS κρατά το πλάτος του σε μικρή οθόνη**: η Φωτογραφία και η Αποστολή δίπλα του είναι στρογγυλά κουμπιά, όπως σε μια συνομιλία.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Η αποστολή απαντά αμέσως**: μια σύντομη δόνηση μόλις την πατήσεις, το πεδίο αδειάζει και το μήνυμα φαίνεται, με την ένδειξη «Αποστολή…», ώστε να μη φύγει ποτέ δύο φορές.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**Η οθόνη δεν μένει πια ανεβασμένη** αφού το πληκτρολόγιο έκλεισε πίσω από ένα παράθυρο, ένα μήνυμα του συστήματος ή μια άλλη εφαρμογή.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Η εισαγωγή συνομιλίας με τις φωτογραφίες της δεν παγώνει πια το Erevos**: η οθόνη κινείται όσο έρχονται τα αρχεία, λέει τι ποσοστό τους έχει έρθει, και το **Άκυρο** τη σταματά. Μια συνομιλία που μεταφέρεται στις κρυφές παίρνει μαζί τις συνομιλίες που εισήχθησαν σε αυτή. Δες [Εισαγμένες συνομιλίες](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**Το relay σου αποδεικνύει το δικό του κλειδί**: κάθε σύνδεση ξεκινά με έναν έλεγχο που περνά μόνο το relay που έχει αυτό το κλειδί, οπότε κανείς ενδιάμεσος δεν μπορεί να περάσει για αυτό. Μόλις το αποδείξει, το Erevos δεν συνδέεται πια σε αυτό χωρίς τον έλεγχο. Το relay σου χρειάζεται ενημέρωση γι’ αυτό.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Διαφάνεια](#transparency), νέο μέρος του οδηγού: τι κρατά ο server πίσω από το Erevos και για πόσο, τι δεν κρατά, και ποιος άλλος βλέπει κάτι.',
  "**What's new**: this list, in Settings → General, by version.": '**Τι νέο υπάρχει**: αυτή η λίστα, στις Ρυθμίσεις → Γενικά, ανά έκδοση.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Τίποτα δεν φαίνεται πίσω από το PIN μιας συνομιλίας**: κανένα μήνυμα μιας συνομιλίας κλειδωμένης με PIN δεν εμφανίζεται πριν γραφτεί το PIN της, και με γυαλί, ταπετσαρία ή στυλ με δική του σκηνή, η οθόνη του PIN είναι πυκνό παγωμένο τζάμι που δεν αφήνει να φανεί τίποτα.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Βιντεοκλήση ομάδας από την κορυφή της ομάδας**: μια μπλε κάμερα δίπλα στο πράσινο ακουστικό, όπως στη συνομιλία με μια επαφή.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Μια ουρά στο relay για κάθε επαφή**: κάθε επαφή γράφει σε ουρά που ξέρει μόνο εκείνη, οπότε το relay δεν μπορεί να καταλάβει ότι δύο επαφές γράφουν στο ίδιο τηλέφωνο, και η διαγραφή ή ο αποκλεισμός κάποιου σβήνει μόνο τη δική του. Το relay σου χρειάζεται ενημέρωση γι’ αυτό.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**Οι κρυφές συνομιλίες, πιο κοντά στις άλλες**: κλείνουν μετά από 30 δευτερόλεπτα στο παρασκήνιο, όχι αμέσως, και ποτέ στη διάρκεια κλήσης ή όσο διαλέγεις φωτογραφία ή αρχείο· όσο είναι ανοιχτές, ένα μήνυμα παίζει τον ήχο του, και οι προεπισκοπήσεις συνδέσμων έχουν εκεί δικό τους διακόπτη. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Κρυφές συνομιλίες που λαμβάνουν όσο είναι κλειστές**: ένας διακόπτης στην κορυφή κάθε θέσης, ανοιχτός στις νέες θέσεις, τις κάνει να λαμβάνουν όπως οι άλλες συνομιλίες σου: οι επαφές τους βλέπουν αμέσως ότι ένα μήνυμα έφτασε, μια ειδοποίηση λέει μόνο «Νέο μήνυμα», και μια κλήση χτυπά χωρίς όνομα. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**Οι κρυφές συνομιλίες κρατούν σε αναμονή και κάνουν εισαγωγή**: ό,τι δεν μπορεί να φύγει τώρα περιμένει, με την ένδειξη «Σε αναμονή», και φεύγει μόνο του μέσω του relay τους· η «Αποστολή αργότερα» δουλεύει εκεί όπως στις άλλες συνομιλίες σου· και μια συνομιλία από Telegram, WhatsApp ή Viber μπορεί να εισαχθεί σε μια κρυφή συνομιλία και να μείνει μόνο εκεί. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**Οι κρυφές συνομιλίες σε λίστα όπως οι δικές σου**: ανοίγουν σε μια λίστα σαν της αρχικής οθόνης, με ό,τι ειπώθηκε τελευταίο και πόσα δεν έχουν διαβαστεί, και κάθε θέση έχει τη δική της Συνομιλία με τον εαυτό μου στην κορυφή της. Δες [Κρυφές συνομιλίες](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Περισσότερα στις κρυφές συνομιλίες**: με τη «Λήψη όσο είναι κλειστές», ό,τι τους έρχεται μέσω Nostr διαβάζεται και όσο είναι κλειστές· κι εκεί μια επαφή προστίθεται από φωτογραφία του κωδικού QR της και μια κρυφή επαφή παίρνει φωτογραφία. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Κρυφές συνομιλίες χωρίς relay**: όπως οι άλλες συνομιλίες σου, μπορούν να ξεκινήσουν μόνο μέσω Nostr: ο σύνδεσμος επαφής τους και ο κωδικός QR τους λένε πού διαβάζουν εκεί, και τα κείμενα και οι αντιδράσεις πηγαίνουν εκεί. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Ομάδες στις κρυφές συνομιλίες**: κάτω από τη λίστα τους, η Νέα ομάδα φτιάχνει μια ομάδα με τις επαφές τους· φαίνεται ανάμεσα στις συνομιλίες τους, πηγαίνει μόνο μέσω του relay τους, και διαβάζεται όσο είναι κλειστές αν η Λήψη όσο είναι κλειστές είναι ανοιχτή. Δες [Κρυφές συνομιλίες](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Χωρίς τη γραμμή «δοκιμαστική έκδοση»**: η αρχική οθόνη δεν τελειώνει πια λέγοντας ότι αυτή είναι δοκιμαστική έκδοση. Ο οδηγός λέει ακόμα ακριβώς τι προστατεύεται, και ότι τίποτα δεν έχει ελεγχθεί ακόμα. Δες [Τι προστατεύεται σήμερα](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**Μενού επαφών στις κρυφές συνομιλίες**: οι Επαφές τους έχουν πια μενού, μόνο με ό,τι είναι δικό τους: εισαγωγή αρχείου .vcf σε αυτές, αποθήκευση των επαφών τους ως αρχείο .vcf, και ανάγνωση κωδικού QR επαφής από φωτογραφία. Ένα Erevos ID που γράφεις εκεί την προσθέτει στις κρυφές συνομιλίες. Δες [Επαφές](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**Το κουμπί απλής κλήσης για περισσότερες επαφές**: το πορτοκαλί πληκτρολόγιο πάνω στη συνομιλία μιας επαφής παίρνει και τον αριθμό της επαφής με την οποία τη συνέδεσες (**Σύνδεση με μια επαφή μου**), πρώτα το κινητό.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Εισαγωγή συνομιλιών Viber**: από το αρχείο HTML της εφαρμογής Android Backup Text for Viber, μόνο τα κείμενα.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Ξεκίνημα χωρίς relay, μέσω Nostr**: **Ξεκίνα χωρίς relay** στη Νέα συνομιλία. Κείμενα, αυτοκόλλητα, αντιδράσεις, διορθώσεις και τα σημάδια «ήρθε» και «διαβάστηκε» πάνε μέσω Nostr πάνω από Tor. Φωτογραφίες, φωνητικά, αρχεία και κλήσεις θέλουν ακόμη relay ή ένα κοντινό τηλέφωνο.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**Το relay έρχεται μόνο του**: όποιος έχει relay που κάνει προσκλήσεις στέλνει μία φορά πρόσκληση σε μια επαφή χωρίς relay, μέσα στη συνομιλία, και το άλλο τηλέφωνο την παίρνει μόνο του.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Ειδοποίηση για νέα έκδοση** (Android): μία φορά τη μέρα το Erevos ρωτά τον server του LPHL και δείχνει μια καρφιτσωμένη γραμμή Erevos και μια ειδοποίηση, μόνο για έκδοση υπογεγραμμένη από τον υπολογιστή εκδόσεων. Κλείνει από Ρυθμίσεις → Γενικά → Ενημερώσεις.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Κλείδωμα συνομιλίας με PIN**: Λεπτομέρειες → Κλείδωμα με PIN, για συνομιλίες και ομάδες. Τίποτα από αυτή δεν φαίνεται στην αναζήτηση, στα μηνύματα με αστέρι ή στις εισαγωγές. Στις κρυφές συνομιλίες δεν ζητά PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Νέο ακουστικό** στα πράσινα πλακίδια: Τηλέφωνο, και η κλήση μέσα στη συνομιλία.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Νέα οθόνη Νέα συνομιλία**: το «Πώς συνδέεσαι τώρα» πάνω πάνω, τρεις μεγάλες κάρτες για τηλέφωνο χωρίς relay (Έχω πρόσκληση, Σύνδεση με LPHL, Ξεκίνα χωρίς relay), και τα τεχνικά κάτω από το «Για προχωρημένους».',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr πιο σταθερό μέσω Tor**: κάθε Nostr relay έχει δική του διαδρομή μέσω Tor, και μετά από αποτυχία δοκιμάζει νέα έξοδο. Πιο καθαρό μήνυμα λάθους στην οθόνη Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Όταν κόβεται η σύνδεση με το relay** ενώ το Erevos περιμένει, το Erevos το καταλαβαίνει και ξανασυνδέεται, εκεί που πριν έμενε κολλημένο.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Πρόσκληση με SMS** (Android): στην κάρτα μιας επαφής του τηλεφώνου, για ένα άτομο, για 2 μέρες. Ο σύνδεσμος ανοίγει μια σελίδα που προσφέρει το Erevos (το APK για Android, το web app για iPhone ή υπολογιστή) και μετά ανοίγει την πρόσκληση. Το QR και η Κοινοποίηση της πρόσκλησης μένουν όπως ήταν.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Διορθώσεις στην πρόσκληση με SMS**: δέχεται και σύνδεσμο που αντιγράφηκε ως /i/#…, ένα παλαιότερο web app ανοίγει κι αυτό την πρόσκληση, και στο iOS 26 λέει ότι η Κοινοποίηση είναι στο •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Κουμπί τηλεφωνικής κλήσης** στις συνομιλίες Erevos και στις συνομιλίες SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Διόρθωση μηνύματος** που έστειλες, έως μία μέρα μετά: σε επαφές, ομάδες και συνδεδεμένες συσκευές, με «Επεξεργασμένο» δίπλα στην ώρα.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**Το Nostr λέει τι έκανε**: «Στάλθηκε μέσω Nostr», και στην οθόνη Nostr τι έκανε τελευταία κάθε relay.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Χρωματιστά κουμπιά κλήσης** πάνω στη συνομιλία: βίντεο μπλε, φωνή πράσινο.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Βέλη για την αρχή και το τέλος της συνομιλίας· τα παλαιότερα μηνύματα έρχονται μόνα τους καθώς κυλάς.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'Οι συνομιλίες που εισάγονται από Telegram και WhatsApp φαίνονται σαν μηνύματα του Erevos: φούσκες, ημέρες, φωτογραφίες, φωνητικά, αναζήτηση.',
  'Dogs instead of cats in the stickers.': 'Σκύλοι αντί για γάτες στα αυτοκόλλητα.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Στιγμιότυπα οθόνης: διακόπτης στις Ρυθμίσεις → Απόρρητο και ασφάλεια.',
  'Hidden chats from New chat: hold it for a second.': 'Κρυφές συνομιλίες από τη Νέα συνομιλία: κράτησέ τη πατημένη ένα δευτερόλεπτο.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Χρωματιστά πλακίδια στην αρχική: Τηλέφωνο πράσινο, Επαφές μωβ, κλειδαριά πορτοκαλί.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Συνομιλία με τον εαυτό μου**, πάντα πρώτη, και **Υπενθύμιση**, το πορτοκαλί καμπανάκι.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Πολυμέσα, σύνδεσμοι και αρχεία** στις Λεπτομέρειες μιας συνομιλίας, με ημερολόγιο και Μετάβαση σε ημέρα.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Εισαγωγή συνομιλίας μέσα από τη συνομιλία: Λεπτομέρειες → Εισαγμένες συνομιλίες.',
  'A closed space can say that a message came while another space is open.': 'Ένας κλειστός χώρος μπορεί να πει ότι ήρθε μήνυμα ενώ είναι ανοιχτός άλλος.',
  'The message menu says when a message went or came through Nostr.': 'Το μενού του μηνύματος λέει πότε ένα μήνυμα πήγε ή ήρθε μέσω Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Στήριξε το Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Ποιος φτιάχνει το Erevos και γιατί, στο Σχετικά με το Erevos· ο οδηγός λέει παντού το γιατί.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Ρυθμίσεις σε 8 ομάδες**, με αναζήτηση: Γενικά, Εμφάνιση, Ειδοποιήσεις, Απόρρητο και ασφάλεια, Relay και δίκτυα, Τηλέφωνο και SMS, Δεδομένα και συσκευές, Για δοκιμές. Το ⋯ της αρχικής κρατά μόνο τα μέρη, και τελευταίες τις Ρυθμίσεις.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Ο Έλεγχος για ενημερώσεις λέει τι εμπόδισε μια ενημέρωση.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    'Η Πρόσκληση σε κάποιον δεν φτιάχνεται από κοινό token· ζητά πρώτα σύνδεση στο relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'Το κοινό token του relay γίνεται μόνο του token του ίδιου του τηλεφώνου (θέλει ενημερωμένο relay).',
  'A relay that refuses through Tor says why.': 'Ένα relay που αρνείται μέσω Tor λέει γιατί.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Λιγότερη μπαταρία στο παρασκήνιο: relay, Tor και κοντινά ραδιόφωνα.',
  'Erevos no longer closes when you make a sticker from a photo.': 'Το Erevos δεν κλείνει πια όταν φτιάχνεις αυτοκόλλητο από φωτογραφία.',
  'Hidden chats’ notices are right.': 'Σωστές ειδοποιήσεις για τις κρυφές συνομιλίες.',
  'Hidden chats by holding New chat.': 'Κρυφές συνομιλίες με κράτημα της Νέας συνομιλίας.',
  'A search for contacts on the Phone.': 'Αναζήτηση επαφών στο Τηλέφωνο.',
  'New chat shows first how to add a contact.': 'Η Νέα συνομιλία δείχνει πρώτα πώς προσθέτεις επαφή.',
  'A call shows over the screen saver, and the screen wakes.': 'Η κλήση φαίνεται πάνω από την προφύλαξη οθόνης, και η οθόνη ξυπνά.',
  'Erevos in other apps’ Share.': 'Το Erevos στην Κοινοποίηση των άλλων εφαρμογών.',
  'A sound for every new message, also while Erevos shows.': 'Ήχος για κάθε νέο μήνυμα, και όσο φαίνεται το Erevos.',
  'The SMS settings say right what holding does.': 'Οι ρυθμίσεις SMS λένε σωστά τι κάνει το κράτημα.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Κάθε εικονίδιο ανοίγει αυτό που γράφει: Erevos, SMS, Τηλέφωνο, Επαφές, widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Μηνύματα μέσω Tor εξ ορισμού**: Μηνύματα, Όλα ή Τίποτα.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Κείμενα μέσω Nostr**: τρία δημόσια relay, μέσω Tor, με εφεδρεία το δικό σου relay μετά από 5 λεπτά.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Μία πρόσκληση για όλα: το relay και η επαφή μαζί.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Κανόνες spam για αποστολείς και αριθμούς εξωτερικού, με το γιατί.',
  '480 stickers in 20 sets.': '480 αυτοκόλλητα σε 20 σετ.',
  'Lighter chats on older phones; QR codes at once.': 'Πιο ελαφριές συνομιλίες σε παλαιότερα τηλέφωνα· QR αμέσως.',
  'Copy code for one-time codes in SMS.': 'Αντιγραφή κωδικού για τους κωδικούς μιας χρήσης στα SMS.',
  'Locked, Erevos keeps receiving.': 'Κλειδωμένο, το Erevos συνεχίζει να λαμβάνει.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Γρηγορότερες επαφές· η ειδοποίηση των κρυφών συνομιλιών μετρά μόνο μηνύματα.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'Το relay δοκιμάζει κάθε διεύθυνση: push, άλλα relay, σύνδεση με LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Το σύρσιμο στις καρτέλες αλλάζει μόνο καρτέλα.',
  'The icons fill the launcher’s shape.': 'Τα εικονίδια γεμίζουν το σχήμα του launcher.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Χρωματιστά εικονίδια (Erevos κόκκινο, Τηλέφωνο πράσινο, SMS μπλε, Επαφές μωβ) και νέο εικονίδιο SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Χρώμα για κάθε εικονίδιο, και η σειρά των κουμπιών του widget.',
  'Swipe to go back, and between tabs.': 'Σύρσιμο για πίσω, και ανάμεσα σε καρτέλες.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Μια ενημέρωση του WebView δεν κλείνει πια το Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Η διαγραφή ή ο αποκλεισμός μιας επαφής σού δίνει νέα ουρά στο relay.',
  'A new contact can take the name of a contact on the phone.': 'Μια νέα επαφή μπορεί να πάρει το όνομα μιας επαφής του τηλεφώνου.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Σύνδεση στο relay με LPHL**, και **προσκλήσεις στο relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Άδειες στο web app, και περισσότερες στο Android· η ειδοποίηση του web app λέει πόσα ήρθαν.',
  'Hidden chats can ring calls while they are closed.': 'Οι κρυφές συνομιλίες μπορούν να χτυπούν κλήσεις ενώ είναι κλειστές.',
  'New keys every month in chats, every week in groups.': 'Νέα κλειδιά κάθε μήνα στις συνομιλίες, κάθε εβδομάδα στις ομάδες.',
  'Linked devices work with the phone off.': 'Οι συνδεδεμένες συσκευές δουλεύουν με το τηλέφωνο κλειστό.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Νέα οθόνη συνομιλίας· QR από φωτογραφία· το Τηλέφωνο για μικρές οθόνες.',
  'Add as contact inside a group.': 'Προσθήκη ως επαφή μέσα σε ομάδα.',
  'Stickers in sets, moving, and your own.': 'Αυτοκόλλητα σε σετ, κινούμενα, και δικά σου.',
  'SMS inside the Erevos chat.': 'SMS μέσα στη συνομιλία του Erevos.',
  'Android updates need the release computer’s signature.': 'Οι ενημερώσεις Android θέλουν την υπογραφή του υπολογιστή εκδόσεων.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Έκδοση για το F-Droid· Σερβοκροατικά· νέα αρίθμηση εκδόσεων.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Πολλά για την ασφάλεια: Argon2id, μηνύματα κρυπτογραφημένα και για το relay, token για κάθε τηλέφωνο, κανένας σύνδεσμος δεν ξεκινά κλήση.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'Οι εισαγωγές από Telegram και WhatsApp φέρνουν φωτογραφίες, βίντεο, φωνητικά και αρχεία.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Ένα τηλέφωνο χωρίς relay μιλά μέσω μιας θέσης στο relay μιας επαφής.',
  // 0.1.14
  'Back to my chats, for hidden chats.': 'Επιστροφή στις συνομιλίες μου, για τις κρυφές συνομιλίες.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'Το Erevos λαμβάνει και χτυπά ακόμη και αφού το διώξεις από τις πρόσφατες εφαρμογές.',
  // 0.1.12
  'Hidden chats can say a message came.': 'Οι κρυφές συνομιλίες μπορούν να πουν ότι ήρθε μήνυμα.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Διορθώσεις: μενού, QR από φωτογραφία, Bluetooth στο Android 17, μεγάλες λίστες.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'Το Τηλέφωνο χωρίς τον κωδικό, αν το επιτρέψεις· widget για την αρχική οθόνη· φίλτρο SMS και Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Οι σύνδεσμοι περιμένουν τον κωδικό· εικονίδια Τηλεφώνου και Επαφών· το Erevos ID σε μια επαφή.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 νέες λειτουργίες: 5 νέες γλώσσες, συνδεδεμένες συσκευές, δημόσιες ομάδες, απαντήσεις, αντιδράσεις, δημοσκοπήσεις, αποστολή αργότερα, το Erevos ως εφαρμογή τηλεφώνου και επαφών, γέφυρες Tor, δακτυλικό αποτύπωμα, Windows και άλλα.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Ειδοποιήσεις SMS στο παρασκήνιο.',
  'The web app comes out with every release.': 'Το web app βγαίνει μαζί με κάθε έκδοση.',
  'Greek in the whole app.': 'Ελληνικά σε όλη την εφαρμογή.',
  'Web Push in the web app.': 'Web Push στο web app.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'Η πρώτη υπογεγραμμένη έκδοση για Android: κρυπτογραφημένες συνομιλίες, κλήσεις, ομάδες, κρυφές συνομιλίες, αντίγραφα ασφαλείας, εισαγωγές, και κοντινά τηλέφωνα χωρίς internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Δύο νέα σετ αυτοκόλλητων με 24 διαθέσεις**: ο **Tux**, ο πιγκουίνος του Linux όπως είναι σχεδιασμένος, και το **Αϊκίντο**, ένας αϊκιντόκα με κεικόγκι και φαρδύ χακάμα, που επίσης υποκλίνεται, κάθεται σε σέιζα και κάνει κυβίστηση.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Νέο σετ αυτοκόλλητων, ο Τάκης**: μια καρικατούρα με σκούρο κοστούμι και μωβ γραβάτα με βουλίτσες, σε 24 διαθέσεις που κινούνται.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Φωτογραφίες, αρχεία και φωνητικά μηνύματα χωρίς relay**: όταν δεν υπάρχει relay ανάμεσα σε σένα και την επαφή σου και εκείνη διαβάζει στο Nostr, ένα φωνητικό μήνυμα πηγαίνει μέσω Nostr όπως ένα κείμενο, μια φωτογραφία έως 3 MB σε κομμάτια, και μια μεγαλύτερη φωτογραφία, ένα βίντεο ή άλλο αρχείο, έως 20 MB, σε έναν κρυπτογραφημένο server αρχείων (Blossom), όλα μέσω Tor. Δες [Μέσω Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Περισσότερη μπαταρία γλιτώνει στο παρασκήνιο, αν το επιλέξεις**: στις Ρυθμίσεις → Ειδοποιήσεις → Στο παρασκήνιο, το Μόνο η σπατάλη μένει η προεπιλογή· το Και τα κοντινά κλείνει και τα ραδιόφωνα για κοντινά τηλέφωνα όσο το Erevos είναι στο παρασκήνιο· το Και ύπνος αφήνει και το τηλέφωνο να κοιμάται, οπότε το Erevos κοιτάζει το relay σου περίπου μία φορά το λεπτό και ένα μήνυμα ή μια κλήση μπορεί να αργήσει ένα-δύο λεπτά. Μόνο σε Android. Δες [Συνομιλία μέσω relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Μια επαφή που διαγράφεις δεν ξαναγυρίζει από παλιό αίτημα**: σε μια ομάδα, ένα μέλος που ζήτησες τον σύνδεσμο επαφής του, ή που ζήτησε τον δικό σου, και που μετά διέγραψες ως επαφή πριν το Erevos ξανακοιτάξει το relay, μπορούσε να προστεθεί ξανά από εκείνο το παλιό αίτημα. Τώρα η διαγραφή το αφήνει αμέσως. Δες [Ομαδικές συνομιλίες](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Κάθε μήνυμα λέει από πού πέρασε**: κράτα πατημένο ένα μήνυμα και το μενού του λέει αν πήγε ή ήρθε μέσω του relay, μέσω Nostr, από κοντινό τηλέφωνο ή μέσω LoRa. Τα μηνύματα από πριν δεν λένε τίποτα. Δες [Μέσω Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**Το φίλτρο ανεπιθύμητων διαβάζει τις λέξεις όπως φαίνονται**: ένα μήνυμα απάτης που αλλάζει ένα γράμμα με ένα όμοιο άλλου αλφαβήτου, ή κρύβει μέσα σε μια λέξη ένα σημάδι που δεν φαίνεται, δεν το ξεγελά πια. Δες [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Πολυμέσα, σύνδεσμοι και αρχεία και στις ομάδες**: στις λεπτομέρειες μιας ομάδας, μια λίστα με τις φωτογραφίες, τα βίντεο, τα φωνητικά, τη μουσική, τα αρχεία και τους συνδέσμους της, κάθε είδος χωριστά κάτω από τους μήνες του, με ημερολόγιο, όπως σε μια συνομιλία επαφής. Ένα πάτημα ανοίγει ή παίζει· κρατημένο, το καθένα πάει στο μήνυμά του. Δες [Ομαδικές συνομιλίες](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Μια επανεκκίνηση του relay δεν φέρνει πια ψεύτικη ειδοποίηση**: αφού το relay σου ξεκινούσε ξανά, μια κρυφή συνομιλία ή ένας κλειστός χώρος έλεγε ξανά Νέο μήνυμα για μηνύματα που είχε ήδη πει. Το relay σου χρειάζεται ενημέρωση γι’ αυτό. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Αντίγραφα στον server σου μέσω Tor**: σε Android, τα αυτόματα αντίγραφα που πηγαίνουν στον δικό σου server ακολουθούν πια την επιλογή του χώρου στις Ρυθμίσεις → Relay και δίκτυα → Tor, όπως το Matrix, οπότε με Tor ο server δεν βλέπει πια πού βρίσκεσαι. Το Και σε server λέει πότε πηγαίνουν μέσω Tor. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Επαναφορά αντιγράφου κατευθείαν από τον server σου**: η Επαναφορά από server, στα Αντίγραφα ασφαλείας, δείχνει τα αντίγραφα στον server σου, τα νεότερα πρώτα, και ανοίγει αυτό που διαλέγεις με τον κωδικό του, χωρίς κατέβασμα με το χέρι, και σε καινούργιο τηλέφωνο. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Αντίγραφα στον server σου και από υπολογιστή και από το web app**: στην εφαρμογή υπολογιστή, τα αυτόματα αντίγραφα πηγαίνουν στον server WebDAV σου όπως στο Android· στο web app, η Αποστολή αντιγράφου τώρα στέλνει ένα εκεί, με server που αφήνει το web app να μπει. Και τα δύο κάνουν επαναφορά από αυτόν. Όχι μέσω Tor. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Έλεγχος επαφής από κοντά με κωδικούς QR**: στον Αριθμό ασφαλείας, στις λεπτομέρειες μιας συνομιλίας, κάθε τηλέφωνο δείχνει έναν κωδικό· φωτογράφισε τον κωδικό στο άλλο τηλέφωνο, κι εκείνοι τον δικό σου. Όταν ταιριάζει, η επαφή σημειώνεται Ελέγχθηκε από κοντά. Δεν στέλνεται τίποτα. Δες [Συνομιλία μέσω relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Έως τρία σπιτικά relay**: στις Ρυθμίσεις → Relay και δίκτυα → Σπιτικό relay, το Προσθήκη κι άλλου σπιτικού relay δίνει σε έναν χώρο έως δύο ακόμα, το καθένα με δική του ουρά. Ο σύνδεσμος επαφής σου και τα μηνύματά σου τα λένε με τη σειρά, και οι επαφές δοκιμάζουν το καθένα όσο τα προηγούμενα δεν απαντούν. Δες [Σπιτικό relay](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Σύστησε δύο επαφές σου μεταξύ τους**: στις λεπτομέρειες της συνομιλίας μιας επαφής, το Σύσταση σε μια επαφή ρωτά εκείνη και άλλη μια επαφή σου, την καθεμία στη συνομιλία σας. Γίνονται επαφές μόνο αν πουν και οι δύο ναι, και κανείς δεν μαθαίνει αν ο άλλος είπε όχι. Δες [Συνομιλία μέσω relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth που δεν παρακολουθείται**: ο τυχαίος αριθμός που στέλνει το τηλέφωνό σου μέσω Bluetooth για να το βρίσκουν τα κοντινά τηλέφωνα άλλαζε μόνο όταν ξεκινούσε ξανά το Erevos· τώρα αλλάζει κάθε εννιά με δώδεκα λεπτά, οπότε κάποιος που ακούει δεν μπορεί να ακολουθήσει το τηλέφωνό σου από μέρος σε μέρος μέσω αυτού. Τα τηλέφωνα με παλιότερο Erevos βρίσκουν ακόμα το δικό σου. Δες [Συνομιλία με κοντινό τηλέφωνο](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**Οι κρυφές συνομιλίες φαίνονται αμέσως**: μόλις το PIN τις ανοίξει, οι συνομιλίες και οι επαφές τους φαίνονται αμέσως, για ανάγνωση, ενώ τελειώνει ό,τι λάμβαναν στο παρασκήνιο· πριν, αυτό μπορούσε να τις καθυστερήσει για πολλή ώρα, επειδή μπορεί να περνά μέσω Tor. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**Ο κωδικός των αντιγράφων σου σε κομμάτια σε φίλους**: στις Ρυθμίσεις → Δεδομένα και συσκευές → Κομμάτια αντιγράφων, δώσε κομμάτια του σε 3 έως 5 επαφές· οποιαδήποτε 2 ή 3 τον δίνουν πίσω, ένα μόνο του δεν δείχνει τίποτα. Το καθένα πηγαίνει μέσα στην κρυπτογράφηση της συνομιλίας σου μαζί τους και το κρατά μόνο το Erevos τους· το τηλέφωνό σου δεν κρατά κανένα. Δες [Κομμάτια αντιγράφων σε φίλους](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Κουμπί πανικού**: στις Ρυθμίσεις → Απόρρητο και ασφάλεια → Κουμπί πανικού, σβήσε ό,τι κρατά εδώ το Erevos με ένα πάτημα, στο Android και στην εφαρμογή web. Στο Android μπορεί να το κάνει και μια εφαρμογή πανικού όπως το Ripple, αλλά μόνο εκείνη στην οποία λες ναι, ελεγμένη από την υπογραφή της. Δες [Κουμπί πανικού](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**Το Erevos σε κοντινό τηλέφωνο, χωρίς internet**: στις Ρυθμίσεις → Γενικά → Δώσε το Erevos σε κοντινό τηλέφωνο, αυτό το τηλέφωνο σερβίρει το Erevos του μέσω του ίδιου Wi-Fi ή του hotspot του για δέκα λεπτά, με έναν κωδικό QR. Ένα τηλέφωνο χωρίς Erevos το κατεβάζει στον browser· ένα με παλιότερο Erevos το παίρνει στις Ενημερώσεις → Από κοντινό τηλέφωνο, που το εγκαθιστά μόνο αν είναι το Erevos, υπογεγραμμένο όπως εκείνο. Δες [Το Erevos σε κοντινό τηλέφωνο](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Κρυφές συνομιλίες με κοντινά τηλέφωνα**: όσο οι κρυφές συνομιλίες είναι ανοιχτές, ή λαμβάνουν όσο είναι κλειστές, φτάνουν στο τηλέφωνο μιας επαφής κοντά με Bluetooth, Wi-Fi Aware, Wi-Fi Direct ή στο ίδιο Wi-Fi, χωρίς internet, όπως οι άλλες σου συνομιλίες. Ο χώρος δεν μαθαίνει ποτέ ότι μια κρυφή επαφή είναι κοντά, και τίποτα στον αέρα δεν ξεχωρίζει τα μηνύματά τους από του χώρου· δεν τα μεταφέρουν ποτέ άλλα τηλέφωνα, και δεν πάνε ποτέ με LoRa ή με SMS. Δες [Κρυφές συνομιλίες](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**Το ίδιο Wi-Fi στο Sailfish OS**: το Erevos στο Sailfish OS βρίσκει τηλέφωνα και υπολογιστές με Erevos στο ίδιο Wi-Fi ή στο hotspot ενός τηλεφώνου και μιλά μαζί τους χωρίς internet, όπως σε υπολογιστή. Δες [Σε Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Οι λήψεις σταματούν στα 100 MB**: ένα αρχείο, ένα αντίγραφο από server ή οποιαδήποτε άλλη λήψη διαβάζεται όπως έρχεται και σταματά μόλις περάσει τα 100 MB, ή λιγότερα όπου τα αρχεία του δικτύου είναι μικρότερα, όπως 20 MB για τα αρχεία του Nostr, οπότε ένας server αρχείων που ορίζει μια επαφή δεν μπορεί πια να γεμίσει τη μνήμη του τηλεφώνου με μια απάντηση χωρίς τέλος. Ένα αντίγραφο σε server επιστρέφει έως 100 MB· ένα μεγαλύτερο κατέβασέ το και άνοιξέ το με την Επαναφορά αντιγράφου. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Εικόνες προφίλ σε Matrix και XMPP**: οι επαφές και τα δωμάτια Matrix δείχνουν την εικόνα τους στη λίστα συνομιλιών, και μπορείς να βάλεις τη δική σου στις οθόνες Matrix και XMPP (Επιλογή φωτογραφίας). Οι εικόνες δεν είναι κρυπτογραφημένες σε κανένα από τα δύο δίκτυα: ο server τις βλέπει. Δες [Matrix](#matrix) και [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Διαχείριση ομάδας XMPP**: οι διαχειριστές μιας ομάδας βάζουν το θέμα της και βγάζουν ή αποκλείουν ανθρώπους, ο ιδιοκτήτης την μετονομάζει και κάνει διαχειριστές, και σε ένα κανάλι ο διαχειριστής βλέπει ποιοι είναι μέσα και μπορεί να τους βγάλει. Δες [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Έλεγχος συσκευής Matrix με κωδικό QR**: όταν και οι δύο πλευρές δεχτούν έναν έλεγχο, το Erevos δείχνει έναν κωδικό για να τον φωτογραφίσει το Element (ή ένα άλλο Erevos), ή φωτογραφίζει τον δικό τους, όπως το Element· η σύγκριση με emoji μένει ένα πάτημα μακριά. Δες [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Σύνδεση στο Matrix με ενιαία είσοδο (SSO)** (Android): όταν ο διακομιστής σου Matrix συνδέει τους ανθρώπους στη δική του σελίδα, όπως το matrix.org, το «Σύνδεση με ενιαία είσοδο (SSO)» την ανοίγει στον περιηγητή και γυρίζει στο Erevos. Δες [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Ένας κλειστός χώρος ειδοποιεί για μηνύματα XMPP**: σε Android, η «Ειδοποίηση για μηνύματα» στο «Όσο αυτός ο χώρος είναι κλειστός», στην οθόνη του XMPP, αφήνει έναν κλειστό χώρο να λέει «Νέο μήνυμα» όταν έρχεται κάτι στο XMPP όσο είναι ανοιχτός άλλος χώρος, ποτέ τι, από ποιον ή σε ποια συνομιλία. Κλειστό μέχρι να το επιλέξεις. Χρειάζεται relay ενημερωμένο γι’ αυτό και έναν server XMPP που στέλνει ειδοποιήσεις σε εφαρμογές που λείπουν· ο server του XMPP μαθαίνει τότε το όνομα του relay, και το relay πότε έρχονται μηνύματα. Δες [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Η σύνδεση ενός υπολογιστή είναι πιο σαφής**: σε υπολογιστή, η οθόνη «Συνδεδεμένες συσκευές» (Ρυθμίσεις → Δεδομένα και συσκευές) ξεκινά πλέον με «Σύνδεση με το τηλέφωνό μου», με το relay του LPHL ήδη συμπληρωμένο και τη «Σύνδεση με LPHL» κάτω από το token, ώστε να μη χρειάζεται να αντιγραφεί token από το τηλέφωνο· και λέει ότι ο κωδικός QR εμφανίζεται μόλις πατηθεί η «Σύνδεση με το τηλέφωνό μου». Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Σβήσε με από παντού**: Ρυθμίσεις → Απόρρητο και ασφάλεια → Σβήσε με από παντού σβήνει ό,τι κρατούν οι servers για τον ανοιχτό χώρο (τις ουρές του στα relay με τα μηνύματα μέσα τους, ό,τι κρατά ένα relay για να στείλει αργότερα, τα αρχεία που περιμένουν εκεί, τις προσκλήσεις που κανείς δεν χρησιμοποίησε), ζητά μέσω Tor από τα relay του Nostr να ξεχάσουν τα κλειδιά στα οποία διαβάζουν οι συνομιλίες σου, και σταματά τον χώρο μέχρι να πατήσεις Ξεκίνα ξανά. Το τηλέφωνό σου κρατά τα πάντα. Μπορείς να αποσυνδεθείς και από Matrix και XMPP και να σβήσεις τον λογαριασμό Nostr που έγινε εδώ. Δες [Σβήσε με από παντού](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Κάθε ουρά relay σε μία λίστα**: οι ουρές που κρατά ένας χώρος στα relay μαζεύονται σε ένα σημείο, και οι έλεγχοι αποτυγχάνουν αν φτιαχτεί νέο είδος ουράς χωρίς να μπει εκεί, ώστε το Σβήσε με από παντού να μην αφήσει καμία πίσω.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP και Nostr σε συνδεδεμένο υπολογιστή**: η σύνδεση ενός υπολογιστή μπορεί να φέρει μαζί και τους λογαριασμούς Matrix και XMPP αυτού του χώρου και το κλειδί των συνομιλιών του Nostr, καθένα συνδεδεμένο εκεί ως νέα συσκευή με δικά της κλειδιά· για έναν υπολογιστή που είναι ήδη συνδεδεμένος, πάτα στο τηλέφωνο «Στείλε τους λογαριασμούς» κάτω από αυτόν. Ένας server Matrix σπάνια αφήνει το τηλέφωνο να συνδέσει τον υπολογιστή: τότε ο υπολογιστής ζητά μία φορά τον κωδικό του Matrix, και τα κλειδιά του λογαριασμού έρχονται από το τηλέφωνο, οπότε δεν χρειάζεται Κλειδί Ασφαλείας ούτε έλεγχος με emoji. Δες [Συνδεδεμένες συσκευές](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Μόνο τα SMS**: όταν το Erevos είναι κλειδωμένο, το εικονίδιο SMS, το κουμπί SMS του widget και η ειδοποίηση για νέο SMS ζητούν τον κωδικό και μετά ανοίγουν μόνο τα SMS. Οτιδήποτε άλλο, καθώς και η πορτοκαλί κλειδαριά **Ξεκλείδωμα όλων**, ζητούν ξανά τον κωδικό και μετά ανοίγουν ολόκληρο το Erevos. Δες [Κλείδωμα με κωδικό](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**Οι συνομιλίες Nostr με κλειδί που έφερες από άλλη εφαρμογή παίρνουν ξανά τα μηνύματά τους**: το Erevos διαβάζει εκεί όπου η άλλη εφαρμογή είπε ότι φτάνουν τα μηνύματά σου, όπως κάνει εκείνη, αντί για τα δικά του τρία relays, φέρνει τα μηνύματα που είναι αποθηκευμένα εκεί και σε παλαιότερες λίστες του κλειδιού, και ξαναδιαβάζει ένα relay όταν αυτό σταματά να στέλνει. Πριν, ένα τέτοιο κλειδί μπορούσε να δείχνει τις συνομιλίες του χωρίς παλιά μηνύματα και να μη λαμβάνει νέα. Δες [Συνομιλίες με άλλες εφαρμογές Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Τα αντίγραφα κρατούν ό,τι χρειάζονται οι κλειστές συνομιλίες**: ένα αντίγραφο κρατά πια και ό,τι χρειάζονται οι κρυφές συνομιλίες για να χτυπούν κλήσεις και να λένε ότι ήρθε μήνυμα όσο είναι κλειστές, και ένας κλειστός χώρος για να λέει ότι ήρθε μήνυμα. Έτσι, μετά από μια επαναφορά, και σε άλλο τηλέφωνο, το **Χτύπημα κλήσεων όταν είναι κλειστές**, η **Ειδοποίηση όταν έρχεται μήνυμα** και το **Και όσο είναι ανοιχτός άλλος χώρος** συνεχίζουν όπως ήταν. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Άνοιγμα άλλου χώρου από την αναζήτηση**: γράψε τον κωδικό ενός άλλου χώρου στην **Αναζήτηση συνομιλιών** της αρχικής οθόνης και πάτα Enter: ο ανοιχτός χώρος κλείνει, χωρίς να μείνει τίποτα από αυτόν, και ανοίγει ο άλλος, όπως με το **Κλείδωμα τώρα** και τον κωδικό του. Παίρνει τον ίδιο χρόνο ό,τι κι αν γράψεις, και ένας λάθος κωδικός, ή ο κωδικός του ανοιχτού χώρου, είναι απλή αναζήτηση. Δες [Δεύτερος κωδικός](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Κουκκίδα για αδιάβαστα αλλού, αν τη θέλεις**: οι κρυφές συνομιλίες με **Λήψη όσο είναι κλειστές** μπορούν να δείχνουν μια μικρή κουκκίδα στον μεγεθυντικό φακό της **Αναζήτησης συνομιλιών** όσο έχουν αδιάβαστο μήνυμα (ο διακόπτης τους **Κουκκίδα για αδιάβαστα**), και ένας χώρος που λέει ότι ήρθε μήνυμα όσο είναι ανοιχτός άλλος μπορεί να δείχνει μία στο λουκέτο πάνω από τις συνομιλίες των άλλων χώρων (**Κουκκίδα στους άλλους χώρους**). Ποτέ πόσα, ούτε πού· κλειστό, εκτός αν το ανοίξεις. Δες [Κρυφές συνομιλίες](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Για να μπεις, φτάνει η πρόσκληση**: σε τηλέφωνο χωρίς relay ακόμα, η **Νέα συνομιλία** δείχνει έναν τρόπο εισόδου, το **Έχω πρόσκληση**. Η σύνδεση με LPHL, το **Ξεκίνα χωρίς relay** και οι ρυθμίσεις του relay είναι στο **Για προχωρημένους**, για όποιον τα ψάχνει. Και μια πρόσκληση στο relay σου δίνει στο relay μόνο ένα όνομα από τυχαία γράμματα και ψηφία για το τηλέφωνο που μπαίνει: το όνομα που γράφεις μένει στο τηλέφωνό σου, όπου το δείχνει η λίστα με τις προσκλήσεις σου. Δες [Συνομιλία μέσω relay](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Τα τηλέφωνα που προσκάλεσες μένουν**: σε relay αυτής της έκδοσης, ένα τηλέφωνο που προσκάλεσες κρατά την πρόσβασή του ακόμα κι όταν φύγει η δική σου, και το ίδιο όσα προσκάλεσε εκείνο· η ανάκληση μιας πρόσκλησης κόβει μόνο εκείνο το ένα τηλέφωνο. Δες [Συνομιλία μέσω relay](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Τα αντίγραφα φέρνουν πίσω το τηλέφωνο όπως ήταν**: ένα αντίγραφο κρατά πια και τις φωτογραφίες, τα αρχεία και τα φωνητικά μηνύματα, σε δικά τους αρχεία δίπλα του, το καθένα κρυπτογραφημένο και δεμένο με το αντίγραφό του· και τον κωδικό πανικού, τις ρυθμίσεις που έρχονται μαζί σου, τις γρήγορες απαντήσεις του Τηλεφώνου και τις κλήσεις που απορρίπτει, τα SMS για αργότερα και τα αυτόματα αντίγραφα με τον server τους, αλλά όχι τον φάκελό τους. Ένα SMS για αργότερα που η ώρα του πέρασε πριν από την επαναφορά περιμένει να το στείλεις ή να το σβήσεις. Ό,τι μένει σε κάθε τηλέφωνο, όπως το δακτυλικό αποτύπωμα, οι φάκελοι και ό,τι επιτρέπει το Android, δεν επανέρχεται ποτέ: μετά από μια επαναφορά, ανοίγουν οι άδειες του Android για τις ενότητες που είναι ενεργές. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Νεότερο αντίγραφο θέλει νεότερο Erevos**: ένα αντίγραφο που έφτιαξε νεότερο Erevos από το δικό σου απορρίπτεται χωρίς να αλλάξει τίποτα, και το Erevos σου ζητά να το αναβαθμίσεις πρώτα στην τελευταία έκδοση. Ένα Erevos πριν από το 6.0.0 δεν ανοίγει αντίγραφα από το 6.0.0 και μετά: αναβάθμισέ το και μετά κάνε την επαναφορά. Δες [Αντίγραφα ασφαλείας](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Κοινοποίηση στη Συλλογή χωρίς μη κρυπτογραφημένο αντίγραφο**: μια φωτογραφία ή ένα αρχείο που κοινοποιεί μια άλλη εφαρμογή στο Erevos κρυπτογραφείται καθώς έρχεται, πριν ανοίξει η **Αποστολή σε**, έτσι στον δρόμο του για τη Συλλογή δεν μένει ποτέ μη κρυπτογραφημένο στο τηλέφωνο. Εκεί μπορεί να είναι ως 4 GB· μια συνομιλία δέχεται ακόμα έως 100 MB. Ένα μεγάλο δείχνει πόσο έχει κρυπτογραφηθεί, με **Ακύρωση**. Δες [Συλλογή](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Δες ένα αρχείο να έρχεται από τον server WebDAV**: ένα αρχείο της Συλλογής που δεν είναι σε αυτή τη συσκευή, όπως μετά από αντίγραφο που επαναφέρθηκε σε νέο τηλέφωνο, δείχνει πόσο από αυτό έχει έρθει από τον server, και το **Άκυρο** το σταματά· ό,τι ήρθε μένει, και την επόμενη φορά έρχονται μόνο τα υπόλοιπα. Η μουσική, τα βίντεο, τα PDF και το **Άνοιγμα με άλλη εφαρμογή** το φέρνουν πρώτα κι αυτά, αντί να αποτυγχάνουν. Δες [Συλλογή](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Τα αντίγραφα ασφαλείας παραλείπουν ό,τι είναι στον server WebDAV και μετά από επανεκκίνηση**: το ότι τα αντίγραφα μιας Συλλογής στον server της είναι πλήρη φυλάγεται μαζί της, έτσι ένα αντίγραφο ασφαλείας που γίνεται αφού το Erevos ξεκινήσει ξανά εξακολουθεί να αφήνει έξω τα κομμάτια της, όσο δεν προστέθηκε ούτε διαγράφηκε κανένα αρχείο από τότε. Το **Η σύνδεση λειτουργεί.** εμφανίζεται πλέον στο χρώμα της επιτυχίας, όχι μιας προειδοποίησης. Δες [Συλλογή](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Σημειώσεις από άλλη εφαρμογή**: μια εφαρμογή του τηλεφώνου, όπως το Fasouli για μια πληρωμή που έρχεται, μπορεί να ζητήσει να κρατηθεί μια σημείωση με την υπενθύμισή της στη Συνομιλία με τον εαυτό μου. Το Erevos σε ρωτά πρώτα, στον χώρο που ανοίγεις. Δες [Πρώτα βήματα](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Αιτήματα πληρωμής**: μια άλλη εφαρμογή, όπως το Fasouli, μπορεί να ζητήσει από το Erevos να στείλει ένα σε επαφή: ένα ποσό και η αιτία του, σε κάρτα. Η επαφή πατά **Πληρώθηκε** όταν πληρώσει, και το **Σημείωσέ το στο Fasouli** το σημειώνει εισπραγμένο εκεί. Το Erevos δεν μεταφέρει χρήματα. Δες [Συνομιλία μέσω relay](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**Ο πανικός ειδοποιεί και το Fasouli**: στο Android, στις Ρυθμίσεις → Απόρρητο και ασφάλεια → Κουμπί πανικού → **Ειδοποίησε άλλες εφαρμογές**, διαλέγεις τις εφαρμογές που ειδοποιεί το Erevos όταν σβήνει, όπως μια εφαρμογή πανικού: το Fasouli τότε κλειδώνει. Καθεμία σε ρωτά πρώτα. Δες [Κουμπί πανικού](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**Η Συλλογή σε πρόγραμμα περιήγησης και στο Sailfish OS**: η εφαρμογή web, και στην αρχική οθόνη ενός iPhone, και το Erevos στο Sailfish OS έχουν τώρα τη Συλλογή. Ένα αρχείο κρυπτογραφείται κομμάτι κομμάτι καθώς διαβάζεται, κι αν το πρόγραμμα περιήγησης μείνει χωρίς χώρο, δεν κρατιέται τίποτα από αυτό. Φωτογραφίες, κείμενα, μουσική και βίντεο έως 256 MB ανοίγουν μόνο στη μνήμη· ένα PDF αποθηκεύεται για να διαβαστεί αλλού. Δες τη [Συλλογή](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**Μεγάλα αρχεία από τη Συλλογή στο Sailfish OS**: η **Αποθήκευση στο τηλέφωνο** γράφει στις Λήψεις ένα αρχείο κάθε μεγέθους κομμάτι κομμάτι, όπως τώρα και η εφαρμογή υπολογιστή, κι όταν ο δίσκος δεν έχει άλλο χώρο, το Erevos το λέει και δεν αφήνει τίποτα μισογραμμένο. Δες τη [Συλλογή](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Είσοδος με Nextcloud**: ο server μιας Συλλογής και ο server των αντιγράφων ασφαλείας μπορούν πλέον να είναι το Nextcloud σου, όπως του LPHL, αυτό με το οποίο συγχρονίζεται το Fasouli, χωρίς να γράψεις κωδικό: πάτα **Είσοδος με Nextcloud**, συνδέσου στον περιηγητή και παραχώρησε πρόσβαση. Το Erevos παίρνει δικό του κωδικό εφαρμογής και δικό του φάκελο εκεί, Erevos/Collection ή Erevos/Backups. Δες [Συλλογή](#collection).",
};
